    "image": "images/spoonacular-657933.jpg",
    "isGlutenFree": false,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Ratatouille Pasta",
        "subtitle": "Forget going out to eat or ordering takeout every time you crave Me...",
        "description": "Forget going out to eat or ordering takeout every time you crave Mediterranean food. Try making Ratatouille Pastan at home. 1 person found this recipe to be scrumptious and satisfying. From preparation to the plate, this recipe takes roughly 45 minutes.",
        "instructions": [
          "Saute the yellow onion in a large skillet or saute pan with enough Olive oil to coat the bottom of the pan, over medium-low heat until tender and translucent. Season with salt and pepper.",
          "Add garlic, saute until fragrant.",
          "Add another tablespoon of Olive oil and the zucchini, eggplant and Italian seasoning. Continue sauteing until the zucchini and eggplant start to break down and become limp and tender.",
          "Add the artichokes and tomatoes. Season with salt and pepper. Bring to a simmer for ten - fifteen minutes. Taste and re-season if needed.",
          "Meanwhile cook the spaghetti to al dente according to package directions.",
          "Toss with pasta and serve with a drizzle of extra-virgin Olive oil and Parmesan cheese."
        ]
      },
      "nl": {
        "title": "Ratatouille-pasta",
        "subtitle": "Vergeet uit eten te gaan of afhaalmaaltijden te bestellen telkens w...",
        "description": "Vergeet uit eten te gaan of afhaalmaaltijden te bestellen telkens wanneer u zin ​​heeft in Mediterraans eten. Probeer thuis Ratatouille Pastan te maken. 1 persoon vond dit recept heerlijk en bevredigend. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Bak de gele ui in een grote koekenpan of bakpan met voldoende olijfolie om de bodem van de pan te bedekken, op middelhoog vuur tot ze gaar en doorschijnend is. Breng op smaak met zout en peper.",
          "Voeg knoflook toe, bak tot het geurig is.",
          "Voeg nog een eetlepel olijfolie toe en de courgette, aubergine en Italiaanse kruiden. Ga door met bakken totdat de courgette en aubergine beginnen af ​​te breken en slap en zacht worden.",
          "Voeg de artisjokken en tomaten toe. Breng op smaak met zout en peper. Breng het geheel tien tot vijftien minuten aan de kook. Proef en breng indien nodig opnieuw op smaak.",
          "Kook ondertussen de spaghetti al dente volgens de aanwijzingen op de verpakking.",
          "Meng met pasta en serveer met een scheutje extra vergine olijfolie en Parmezaanse kaas."
        ]
      },
      "fr": {
        "title": "Pâtes Ratatouille",
        "subtitle": "Oubliez d'aller manger au restaurant ou de commander des plats à em...",
        "description": "Oubliez d'aller manger au restaurant ou de commander des plats à emporter chaque fois que vous avez envie de cuisine méditerranéenne. Essayez de préparer des pâtes Ratatouille à la maison. 1 personne a trouvé cette recette délicieuse et satisfaisante. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Faire revenir l'oignon jaune dans une grande poêle ou une sauteuse avec suffisamment d'huile d'olive pour enrober le fond de la poêle, à feu moyen-doux jusqu'à ce qu'il soit tendre et translucide. Assaisonner de sel et de poivre.",
          "Ajouter l'ail, faire revenir jusqu'à ce qu'il soit parfumé.",
          "Ajoutez une autre cuillère à soupe d'huile d'olive et les courgettes, les aubergines et l'assaisonnement italien. Continuez à faire sauter jusqu'à ce que les courgettes et les aubergines commencent à se décomposer et à devenir molles et tendres.",
          "Ajoutez les artichauts et les tomates. Assaisonner de sel et de poivre. Portez à ébullition pendant dix à quinze minutes. Goûtez et réassaisonnez si nécessaire.",
          "Pendant ce temps, faites cuire les spaghettis al dente selon les instructions sur l'emballage.",
          "Mélanger avec des pâtes et servir avec un filet d'huile d'olive extra vierge et du parmesan."
        ]
      }
    },
