    "translations": {
      "en": {
        "title": "Garam Masala Pork Chops with Mint Yogurt and Spiced Couscous",
        "subtitle": "Garam Masala Pork Chops with Mint Yogurt and Spiced Couscous might...",
        "description": "Garam Masala Pork Chops with Mint Yogurt and Spiced Couscous might be just the Indian recipe you are searching for. From preparation to the plate, this recipe takes approximately 45 minutes.",
        "instructions": [
          "Chops:Trim pork chops of excess fat. Rub garam masala into chops (both sides).",
          "Place on a plate, cover and refrigerate for 6-8 hours, to allow flavors to penetrate.Chop the mint and stir into the yogurt and refrigerate for the same period as the pork chops.Preheat broiler. Spray broiler rack with nonstick cooking spray. Broil chops for about 5 minutes each side. Alternately, grill chops over direct heat until well marked on both sides, move to indirect heat, cover loosely in foil, and cook until internal temp reaches 145F.",
          "Remove from heat and allow to rest 3 minutes.",
          "Serve with mint yogurt.Note: *Garam Masala is available in specialty stores and many larger grocery stores.Spiced Couscous:In a medium saucepan bring the broth, raisins, olive oil, cumin, cayenne and salt to a boil. Stir in the couscous, bring back to a boil, cover and remove from the heat. Set aside for 5 minutes.Juice the lemon and stir into the couscous with the sesame seeds.",
          "Serve."
        ]
      },
      "nl": {
        "title": "Garam Masala varkenskarbonades met muntyoghurt en gekruide couscous",
        "subtitle": "Garam Masala varkenskarbonades met muntyoghurt en gekruide couscous...",
        "description": "Garam Masala varkenskarbonades met muntyoghurt en gekruide couscous is misschien wel precies het Indiase recept waar u naar op zoek bent. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Karbonades: Snijd het overtollige vet van de karbonades. Wrijf garam masala in karbonades (beide kanten).",
          "Leg ze op een bord, dek af en zet 6-8 uur in de koelkast, zodat de smaken kunnen doordringen. Hak de munt fijn, roer door de yoghurt en laat even lang in de koelkast staan ​​als de karbonades. Verwarm de grill voor. Spuit het grillrek in met anti-aanbakspray. Rooster de karbonades ongeveer 5 minuten per kant. Als alternatief kunt u de stukken grillen op directe hitte tot ze aan beide kanten goed gemarkeerd zijn, op indirecte hitte zetten, losjes in folie bedekken en koken tot de interne temperatuur 145F bereikt.",
          "Haal van het vuur en laat 3 minuten rusten.",
          "Serveer met muntyoghurt. Opmerking: *Garam Masala is verkrijgbaar in speciaalzaken en veel grotere supermarkten. Gekruide couscous: Breng in een middelgrote pan de bouillon, rozijnen, olijfolie, komijn, cayennepeper en zout aan de kook. Roer de couscous erdoor, breng opnieuw aan de kook, dek af en haal van het vuur. Laat 5 minuten staan. Pers de citroen uit en roer deze met de sesamzaadjes door de couscous.",
          "Dienen."
        ]
      },
      "fr": {
        "title": "Côtelettes de porc au garam masala avec yaourt à la menthe et couscous épicé",
        "subtitle": "Les côtelettes de porc au garam masala avec du yogourt à la menthe...",
        "description": "Les côtelettes de porc au garam masala avec du yogourt à la menthe et du couscous épicé pourraient bien être la recette indienne que vous recherchez. 2 personnes ont réalisé cette recette et la referaient. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Côtelettes : Débarrassez les côtelettes de porc de l'excès de gras. Frotter le garam masala sur les côtelettes (des deux côtés).",
          "Placer sur une assiette, couvrir et réfrigérer pendant 6 à 8 heures pour permettre aux arômes de pénétrer. Hachez la menthe, incorporez-la au yaourt et réfrigérez pendant la même période que les côtelettes de porc. Préchauffez le gril. Vaporiser la grille du gril avec un enduit à cuisson antiadhésif. Faire griller les côtelettes environ 5 minutes de chaque côté. Alternativement, faites griller les côtelettes à feu direct jusqu'à ce qu'elles soient bien marquées des deux côtés, passez à chaleur indirecte, couvrez légèrement de papier d'aluminium et faites cuire jusqu'à ce que la température interne atteigne 145F.",
          "Retirer du feu et laisser reposer 3 minutes.",
          "Servir avec du yaourt à la menthe.Remarque : *Le Garam Masala est disponible dans les magasins spécialisés et dans de nombreuses grandes épiceries.Couscous épicé : Dans une casserole moyenne, porter à ébullition le bouillon, les raisins secs, l'huile d'olive, le cumin, le poivre de Cayenne et le sel. Incorporer le couscous, porter à ébullition, couvrir et retirer du feu. Laisser reposer 5 minutes. Presser le citron et incorporer au couscous avec les graines de sésame.",
          "Servir."
        ]
      }
    },
