    "servings": 16,
    "category": [
      "dessert"
    ],
    "image": "images/spoonacular-641284.jpg",
    "isGlutenFree": false,
    "isNutFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Dark Shadows Baileys Chocolate Cheesecake Brownies",
        "subtitle": "Dark Shadows Baileys Chocolate Cheesecake Brownies is an American r...",
        "description": "Dark Shadows Baileys Chocolate Cheesecake Brownies is an American recipe that serves 16. Head to the store and pick up baking powder, walnuts, eggs, and a few other things to make it today. It works well as a dessert. 8 people found this recipe to be flavorful and satisfying. From preparation to the plate, this recipe takes approximately 45 minutes.",
        "instructions": [
          "Place the cream cheese, sugar, egg yolk and Baileys Irish Cream in the bowl of a food processor and process until smooth.Directions for Brownies:Preheat the oven to 350 degrees. Lightly grease an 8-by-8-inch baking pan with cooking spray. To make removing the brownies easy, line the pan lengthwise and widthwise with two 7-by-12-inch sheets of parchment paper or aluminum foil, shiny side up, and use the overhang as handles.",
          "Place the chocolate in a small heatproof bowl and set in a wide pan or skillet of hot water. Set aside for 5 minutes, stirring 4 to 5 times, and let it melt completely. Stir until smooth. In a medium bowl, whisk the flour, cocoa, baking powder, and salt until well blended. Set aside.With a stand or hand mixer set on low speed, beat the butter and sugar in a medium bowl until well blended. Beat in the eggs, one at a time, until fully blended, scraping down the sides and bottom of the bowl as necessary. Beat in the vanilla until blended. Alternately blend the dry ingredients and the melted chocolate into the egg mixture in increments. Using a rubber spatula or wooden spoon, fold in the walnuts. Stop when the ingredients are just blended. Scrape the batter into the prepared baking pan and spread evenly. Set aside.",
          "Place large spoonfuls of the cheesecake mixture on top of the chocolate mixture and, using a butter knife, swirl to partially combine.",
          "Place large spoonfuls of the cheesecake mixture on top of the chocolate mixture and, using a butter knife, swirl to partially combine.",
          "Bake for 45-50 minutes or until set (do not over-bake)."
        ]
      },
      "nl": {
        "title": "Dark Shadows Baileys Chocolade Cheesecake Brownies",
        "subtitle": "Dark Shadows Baileys Chocolate Cheesecake Brownies is een Amerikaan...",
        "description": "Dark Shadows Baileys Chocolate Cheesecake Brownies is een Amerikaans recept voor 16 personen. Ga naar de winkel en koop bakpoeder, walnoten, eieren en nog een paar andere dingen om het vandaag nog te maken. Het werkt goed als dessert. 8 mensen vonden dit recept smaakvol en bevredigend. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Doe de roomkaas, suiker, eigeel en Baileys Irish Cream in de kom van een keukenmachine en maal tot een gladde massa. Gebruiksaanwijzing voor Brownies: Verwarm de oven voor op 350 graden. Vet een bakvorm van 8 bij 8 inch licht in met kookspray. Om het verwijderen van de brownies gemakkelijk te maken, bekleedt u de pan in de lengte en breedte met twee vellen perkamentpapier of aluminiumfolie van 7 bij 12 inch, met de glanzende kant naar boven, en gebruikt u het overhangende gedeelte als handgrepen.",
          "Doe de chocolade in een kleine hittebestendige kom en zet deze in een grote pan of koekenpan met heet water. Laat het 5 minuten staan, roer 4 tot 5 keer en laat het volledig smelten. Roer tot een gladde massa. Klop in een middelgrote kom de bloem, cacao, bakpoeder en zout tot alles goed gemengd is. Zet opzij. Met een standaard of handmixer op lage snelheid klop je de boter en de suiker in een middelgrote kom tot ze goed gemengd zijn. Klop de eieren één voor één erdoor tot ze volledig gemengd zijn. Schraap indien nodig langs de zijkanten en de bodem van de kom. Klop de vanille erdoor tot het gemengd is. Meng afwisselend de droge ingrediënten en de gesmolten chocolade in stappen door het eimengsel. Gebruik een rubberen spatel of houten lepel om de walnoten erdoor te vouwen. Stop wanneer de ingrediënten net gemengd zijn. Schep het beslag in de voorbereide bakvorm en verdeel het gelijkmatig. Zet opzij.",
          "Plaats grote lepels cheesecakemengsel op het chocolademengsel en draai met een botermes om het gedeeltelijk te combineren.",
          "Plaats grote lepels cheesecakemengsel op het chocolademengsel en draai met een botermes om het gedeeltelijk te combineren.",
          "Bak gedurende 45-50 minuten of tot het gaar is (niet te lang bakken)."
        ]
      },
      "fr": {
        "title": "Brownies au gâteau au fromage et au chocolat Baileys Dark Shadows",
        "subtitle": "Les brownies au cheesecake au chocolat Baileys Dark Shadows sont un...",
        "description": "Les brownies au cheesecake au chocolat Baileys Dark Shadows sont une recette américaine pour 16 personnes. Rendez-vous au magasin et procurez-vous de la levure chimique, des noix, des œufs et quelques autres éléments pour le préparer aujourd'hui. Cela fonctionne bien comme dessert. 8 personnes ont trouvé cette recette savoureuse et satisfaisante. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Placez le fromage à la crème, le sucre, le jaune d'œuf et la Baileys Irish Cream dans le bol d'un robot culinaire et mélangez jusqu'à consistance lisse. Instructions pour les brownies : Préchauffez le four à 350 degrés. Graisser légèrement un plat allant au four de 8 x 8 pouces avec un enduit à cuisson. Pour faciliter le retrait des brownies, tapissez le moule dans le sens de la longueur et de la largeur avec deux feuilles de papier parchemin ou de papier d'aluminium de 7 x 12 pouces, côté brillant vers le haut, et utilisez le surplomb comme poignées.",
          "Placez le chocolat dans un petit bol résistant à la chaleur et placez-le dans une grande casserole ou une poêle remplie d'eau chaude. Laisser reposer 5 minutes en remuant 4 à 5 fois et laisser fondre complètement. Remuer jusqu'à consistance lisse. Dans un bol moyen, fouetter la farine, le cacao, la levure chimique et le sel jusqu'à ce que le tout soit bien mélangé. Réserver. À l'aide d'un batteur sur socle ou à main réglé à basse vitesse, battre le beurre et le sucre dans un bol moyen jusqu'à ce que le tout soit bien mélangé. Incorporer les œufs, un à la fois, jusqu'à ce qu'ils soient complètement mélangés, en raclant les parois et le fond du bol si nécessaire. Incorporer la vanille jusqu'à homogénéité. Mélangez alternativement les ingrédients secs et le chocolat fondu au mélange d'œufs, par incréments. À l'aide d'une spatule en caoutchouc ou d'une cuillère en bois, incorporez les noix. Arrêtez-vous lorsque les ingrédients sont juste mélangés. Versez la pâte dans le moule préparé et étalez-la uniformément. Annuler.",
          "Placez de grosses cuillerées du mélange de cheesecake sur le mélange de chocolat et, à l'aide d'un couteau à beurre, remuez pour combiner partiellement.",
          "Placez de grosses cuillerées du mélange de cheesecake sur le mélange de chocolat et, à l'aide d'un couteau à beurre, remuez pour combiner partiellement.",
          "Cuire au four pendant 45 à 50 minutes ou jusqu'à ce que le tout soit pris (ne pas trop cuire)."
        ]
      }
    },
