    "translations": {
      "en": {
        "title": "Vegan Strawberry Shortcake served with Vegan Whipped Cream",
        "subtitle": "Vegan Strawberry Shortcake served with Vegan Whipped Cream might be...",
        "description": "Vegan Strawberry Shortcake served with Vegan Whipped Cream might be just the dessert you are searching for. It can be enjoyed any time, but it is especially good for Mother's Day. 23 people found this recipe to be flavorful and satisfying. If you have vegetable oil, salt, turbinado sugar, and a few other ingredients on hand, you can make it. It is a good option if you're following a dairy free diet. From preparation to the plate, this recipe takes roughly 45 minutes. This score is not so spectacular. Users who liked this recipe also liked Vegan Strawberry Shortcake With Whipped Cream, Easy Vegan and Gluten-Free Pancakes (Strawberry Shortcake + Whipped Cream), and Easy Strawberry Shortcake with Whipped Cream.",
        "instructions": [
          "Preheat your oven to 400 degrees F.",
          "Add the sliced strawberries to a glass bowl and refrigerate until ready to use.",
          "Combine the flours, baking soda and salt in a medium-sized bowl and mix together well.",
          "In a small bowl, add 1 teaspoon water and the sugar, and mix together a bit to help dissolve the sugar.",
          "In a large bowl, combine the almond milk, vinegar, oil, sugar and almond extract.",
          "Whisk together.",
          "Make a well in the center of the dry ingredients and gradually add the wet ingredients.",
          "Mix everything together until combined.",
          "Line two baking sheets with parchment paper.",
          "Drop the batter by generous tablespoons, a few inches apart on the sheets (I recommend 5 per baking sheet).",
          "Bake for 10-12 minutes, or until the shortcakes are just slightly golden.",
          "Allow the shortcakes to cool, then slice them in half with a serrated knife.",
          "Add a generous dollop of whipped topping to the bottom half, then a spoonful of strawberries on top of that. Top with the remaining shortcake half.",
          "Add a bit more whipped topping to the top of the shortcake, and spoon a few of the strawberries over it.",
          "Serve on individual dessert plates."
        ]
      },
      "nl": {
        "title": "Vegan Strawberry Shortcake geserveerd met veganistische slagroom",
        "subtitle": "Vegan Strawberry Shortcake geserveerd met Vegan Slagroom is misschi...",
        "description": "Vegan Strawberry Shortcake geserveerd met Vegan Slagroom is misschien wel het dessert waar je naar op zoek bent. Je kunt er op elk moment van genieten, maar het is vooral lekker voor Moederdag. 23 mensen vonden dit recept smaakvol en bevredigend. Als je plantaardige olie, zout, turbinadosuiker en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het is een goede optie als u een zuivelvrij dieet volgt. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Deze score is niet zo spectaculair. Gebruikers die dit recept lekker vonden, genoten ook van Vegan Strawberry Shortcake met slagroom, Easy Vegan en glutenvrije pannenkoekjes (Strawberry Shortcake + Slagroom) en Easy Strawberry Shortcake met slagroom.",
        "instructions": [
          "Verwarm uw oven voor op 400 graden F.",
          "Doe de gesneden aardbeien in een glazen kom en zet in de koelkast tot ze klaar zijn voor gebruik.",
          "Doe de bloem, het bakpoeder en het zout in een middelgrote kom en meng goed.",
          "Voeg in een kleine kom 1 theelepel water en de suiker toe en meng een beetje om de suiker te helpen oplossen.",
          "Meng in een grote kom de amandelmelk, azijn, olie, suiker en amandelextract.",
          "Klop samen.",
          "Maak een kuiltje in het midden van de droge ingrediënten en voeg geleidelijk de natte ingrediënten toe.",
          "Meng alles tot een geheel.",
          "Bekleed twee bakplaten met bakpapier.",
          "Laat het beslag met royale eetlepels, een paar centimeter uit elkaar, op de bakplaten vallen (ik raad 5 per bakplaat aan).",
          "Bak gedurende 10-12 minuten, of totdat de shortcakes net goudbruin zijn.",
          "Laat de shortcakes afkoelen en snij ze vervolgens doormidden met een gekarteld mes.",
          "Voeg een flinke klodder opgeklopte topping toe aan de onderste helft en daarbovenop een lepel aardbeien. Bestrijk met de resterende shortcake-helft.",
          "Voeg nog wat opgeklopte topping toe aan de bovenkant van de shortcake en schep er een paar aardbeien overheen.",
          "Serveer op individuele dessertbordjes."
        ]
      },
      "fr": {
        "title": "Shortcake végétalien aux fraises servi avec de la crème fouettée végétalienne",
        "subtitle": "Le shortcake végétalien aux fraises servi avec de la crème fouettée...",
        "description": "Le shortcake végétalien aux fraises servi avec de la crème fouettée végétalienne pourrait être exactement le dessert que vous recherchez. On peut le déguster à tout moment, mais il est particulièrement bon pour la fête des mères. 23 personnes ont trouvé cette recette savoureuse et satisfaisante. Si vous avez de l’huile végétale, du sel, du sucre turbinado et quelques autres ingrédients sous la main, vous pouvez le préparer. C'est une bonne option si vous suivez un régime sans produits laitiers. De la préparation à l'assiette, cette recette prend environ 45 minutes. Ce score n'est pas si spectaculaire. Les utilisateurs qui ont aimé cette recette ont également aimé Shortcake végétalien aux fraises avec crème fouettée, Crêpes faciles végétaliennes et sans gluten (Shortcake aux fraises + crème fouettée) et Shortcake facile aux fraises avec crème fouettée.",
        "instructions": [
          "Préchauffez votre four à 400 degrés F.",
          "Ajouter les fraises tranchées dans un bol en verre et réfrigérer jusqu'au moment de les utiliser.",
          "Mélanger les farines, le bicarbonate de soude et le sel dans un bol de taille moyenne et bien mélanger.",
          "Dans un petit bol, ajoutez 1 cuillère à café d'eau et le sucre, et mélangez un peu pour aider à dissoudre le sucre.",
          "Dans un grand bol, mélanger le lait d'amande, le vinaigre, l'huile, le sucre et l'extrait d'amande.",
          "Fouetter ensemble.",
          "Faire un puits au centre des ingrédients secs et ajouter progressivement les ingrédients humides.",
          "Mélangez le tout jusqu'à ce que le tout soit combiné.",
          "Tapisser deux plaques à pâtisserie de papier sulfurisé.",
          "Déposez la pâte par cuillères à soupe généreuses, espacées de quelques centimètres sur les plaques (je recommande 5 par plaque à pâtisserie).",
          "Cuire au four pendant 10 à 12 minutes ou jusqu'à ce que les sablés soient légèrement dorés.",
          "Laissez refroidir les sablés, puis coupez-les en deux avec un couteau dentelé.",
          "Ajoutez une généreuse cuillerée de garniture fouettée dans la moitié inférieure, puis une cuillerée de fraises par-dessus. Garnir avec la moitié restante du shortcake.",
          "Ajoutez un peu plus de garniture fouettée sur le dessus du shortcake et versez quelques fraises dessus.",
          "Servir dans des assiettes à dessert individuelles."
        ]
      }
    },
