        "subtitle": "Need a gluten free, primal, and ketogenic main course?",
        "description": "Need a gluten free, primal, and ketogenic main course? Easy Slow Cooker Whole Chicken With Rosemary could be an excellent recipe to try. 4 people have tried and liked this recipe. Head to the store and pick up chicken, pepper, paprika, and a few other things to make it today. From preparation to the plate, this recipe takes approximately 7 hours and 10 minutes. It is brought to you by Pink When. This score is solid.",
