    "image": "images/spoonacular-637016.jpg",
    "isGlutenFree": true,
    "isNutFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
