        "description": "Dump Cake prend environ 45 minutes du début à la fin. Cette recette en sert 12. Quelques personnes ont vraiment aimé ce dessert. 10 personnes ont réalisé cette recette et la referaient. Dump Cake : un favori facile à partager avec un mélange à gâteau et des baies congelées, un gâteau aux pommes \"dump\" - aucun mélange à gâteau nécessaire !",
