    "translations": {
      "en": {
        "title": "Fresh Peach Margarita With Lime Sugar",
        "subtitle": "If you have around 45 minutes to spend in the kitchen, Fresh Peach...",
        "description": "If you have around 45 minutes to spend in the kitchen, Fresh Peach Margarita With Lime Sugar might be an awesome gluten free, dairy free, lacto ovo vegetarian, and vegan recipe to try. This recipe serves 2. If you have ice, juice of lime, orange liquor, and a few other ingredients on hand, you can make it. 3 people have tried and liked this recipe. It works well as a beverage. This score is rather bad.",
        "instructions": [
          "Add 1/2 teaspoon of finely minced lime zest to 1/4 cup granulated sugar and set aside for about 30 minutes, stirring occasionally.For a pretty presentation, coat the rims of the glasses you are using with lime sugar (of course you can alternatively use plain white sugar).  Do this by rubbing the rim with a lime wedge and then placing the rim into a plate that has the sugar in it until the rim is coated with sugar.",
          "Place all ingredients into the blender and puree.",
          "Add a little cold water if it is too thick.  Either chill all ingredients before making or add some ice cubes after you have made the margarita and stir it until it is as cold as you like and strain it into your glasses (or serve on the rocks)."
        ]
      },
      "nl": {
        "title": "Verse Perzik Margarita Met Limoensuiker",
        "subtitle": "Als je ongeveer 45 minuten de tijd hebt om in de keuken door te bre...",
        "description": "Als je ongeveer 45 minuten de tijd hebt om in de keuken door te brengen, is Verse Perzikmargarita met Limoensuiker wellicht een geweldig glutenvrij, zuivelvrij, lacto ovo-vegetarisch en veganistisch recept om uit te proberen. Dit recept is voor 2 personen. Als je ijs, limoensap, sinaasappellikeur en een paar andere ingrediënten bij de hand hebt, kun je het maken. 3 mensen hebben dit recept geprobeerd en vonden het leuk. Het werkt goed als drank. Deze score is nogal slecht.",
        "instructions": [
          "Voeg 1/2 theelepel fijngehakte limoenschil toe aan 1/4 kopje kristalsuiker en laat ongeveer 30 minuten staan, af en toe roeren. Voor een mooie presentatie bestrijkt u de randen van de glazen die u gebruikt met limoensuiker (u kunt natuurlijk ook gewone witte suiker gebruiken).  Doe dit door over de rand te wrijven met een schijfje limoen en de rand vervolgens in een bord met suiker te plaatsen totdat de rand bedekt is met suiker.",
          "Doe alle ingrediënten in de blender en pureer.",
          "Voeg een beetje koud water toe als het te dik is.  Laat alle ingrediënten afkoelen voordat je ze gaat maken, of voeg wat ijsblokjes toe nadat je de margarita hebt gemaakt en roer het tot het zo koud is als je wilt en zeef het in je glazen (of serveer het op de rotsen)."
        ]
      },
      "fr": {
        "title": "Margarita aux pêches fraîches avec sucre au citron vert",
        "subtitle": "Si vous avez environ 45 minutes à consacrer à la cuisine, la margar...",
        "description": "Si vous avez environ 45 minutes à consacrer à la cuisine, la margarita aux pêches fraîches et au sucre citron vert pourrait être une superbe recette sans gluten, sans produits laitiers, lacto ovo végétarienne et végétalienne à essayer. Cette recette en sert 2. Si vous avez de la glace, du jus de citron vert, de la liqueur d'orange et quelques autres ingrédients sous la main, vous pouvez le préparer. 3 personnes ont essayé et aimé cette recette. Cela fonctionne bien comme boisson. Ce score est plutôt mauvais.",
        "instructions": [
          "Ajoutez 1/2 cuillère à café de zeste de citron vert finement haché à 1/4 tasse de sucre cristallisé et laissez reposer environ 30 minutes en remuant de temps en temps. Pour une jolie présentation, enduisez les bords des verres que vous utilisez avec du sucre de citron vert (vous pouvez bien sûr également utiliser du sucre blanc nature).  Pour ce faire, frottez le bord avec un quartier de citron vert, puis placez le bord dans une assiette contenant du sucre jusqu'à ce que le bord soit recouvert de sucre.",
          "Placer tous les ingrédients dans le mixeur et réduire en purée.",
          "Ajoutez un peu d'eau froide si elle est trop épaisse.  Refroidissez tous les ingrédients avant de préparer ou ajoutez quelques glaçons après avoir préparé la margarita et remuez jusqu'à ce qu'elle soit aussi froide que vous le souhaitez et filtrez-la dans vos verres (ou servez-la sur des glaces)."
        ]
      }
    },
