    "translations": {
      "en": {
        "title": "Cinnamon French Toast Sticks",
        "subtitle": "Cinnamon French Toast Sticks might be a good recipe to expand your...",
        "description": "Cinnamon French Toast Sticks might be a good recipe to expand your breakfast recipe box. A mixture of icing sugar, milk, fruit, and a handful of other ingredients are all it takes to make this recipe so delicious. This recipe from Afrolems has 4 fans. It is a good option if you're following a lacto ovo vegetarian diet. From preparation to the plate, this recipe takes roughly 45 minutes. Not a lot of people really liked this American dish. This score is solid.",
        "instructions": [
          "Slice your bread into smaller rectangular sticks",
          "In a bowl, whisk your egg, milk, 1 tablespoon of honey, 1 tablespoon of cinnamon powder.Dip your bread in the mix, turn on both sides and set aside",
          "In a pan on low heat, heat up your butter and fry your bread sticks.",
          "Serve your french toast sticks with the chopped fruits, drizzle the rest of the honey, sprinkle the rest of the cinnamon powder and icing sugar.P:S – If you are having it as a dessert, you can add a scoop of ice-cream to it."
        ]
      },
      "nl": {
        "title": "Kaneel wentelteefjes",
        "subtitle": "Kaneel-wentelteefjes zijn misschien een goed recept om je ontbijtre...",
        "description": "Kaneel-wentelteefjes zijn misschien een goed recept om je ontbijtreceptendoos uit te breiden. Een mengsel van poedersuiker, melk, fruit en een handvol andere ingrediënten is alles wat nodig is om dit recept zo heerlijk te maken. Dit recept van Afrolems heeft 4 fans. Het is een goede optie als je een lacto-ovo-vegetarisch dieet volgt. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Niet veel mensen hielden echt van dit Amerikaanse gerecht. Deze score is solide.",
        "instructions": [
          "Snijd je brood in kleinere rechthoekige stokjes",
          "Klop in een kom het ei, de melk, 1 eetlepel honing en 1 eetlepel kaneelpoeder. Doop je brood in het mengsel, draai het aan beide kanten en zet het opzij.",
          "Verhit de boter in een pan op laag vuur en bak de broodstengels.",
          "Serveer je wentelteefjes met het gehakte fruit, besprenkel de rest van de honing, strooi de rest van het kaneelpoeder en de poedersuiker. P:S – Als je het als dessert eet, kun je er een bolletje ijs aan toevoegen."
        ]
      },
      "fr": {
        "title": "Bâtonnets de pain perdu à la cannelle",
        "subtitle": "Les bâtonnets de pain perdu à la cannelle pourraient être une bonne...",
        "description": "Les bâtonnets de pain perdu à la cannelle pourraient être une bonne recette pour élargir votre boîte de recettes de petit-déjeuner. Un mélange de sucre glace, de lait, de fruits et une poignée d'autres ingrédients suffisent pour rendre cette recette si délicieuse. Cette recette d'Afrolems a 4 fans. C'est une bonne option si vous suivez un régime lacto-ovo-végétarien. De la préparation à l'assiette, cette recette prend environ 45 minutes. Peu de gens ont vraiment aimé ce plat américain. Ce score est solide.",
        "instructions": [
          "Coupez votre pain en petits bâtonnets rectangulaires",
          "Dans un bol, fouettez votre œuf, le lait, 1 cuillère à soupe de miel, 1 cuillère à soupe de cannelle en poudre. Trempez votre pain dans le mélange, retournez-le des deux côtés et réservez.",
          "Dans une poêle à feu doux, faites chauffer votre beurre et faites revenir vos gressins.",
          "Servez vos bâtonnets de pain perdu avec les fruits hachés, arrosez du reste de miel, saupoudrez du reste de cannelle en poudre et de sucre glace. P:S – Si vous le prenez en dessert, vous pouvez y ajouter une boule de glace."
        ]
      }
    },
