    "translations": {
      "en": {
        "title": "Stuffed Artichoke Main Dish",
        "subtitle": "Stuffed Artichoke Main Dish is a gluten free recipe with 2 servings.",
        "description": "Stuffed Artichoke Main Dish is a gluten free recipe with 2 servings. 18 people have tried and liked this recipe. A few people really liked this main course. From preparation to the plate, this recipe takes approximately 1 hour.",
        "instructions": [
          "Pull apart center leaves of artichoke",
          "Cut the center so that you take the prickly center",
          "Use spoon to get all that out so you only have the center being empty",
          "Add a bit of lemon juice to make sure it doesn't change color",
          "Add artichoke to boiling water",
          "Let boil for 10 min so it gets kind of soft",
          "Take out",
          "Add cold water so it cools",
          "Cut the edges of artichoke",
          "How to make the stuffing.Boil the potato, or put into microwave to cook it up. (it just needs to be soft)In a sauce pan at med-high heat add the olive oil, rosemary, maple syrup, crushed and finely sliced garlic and the chicken.",
          "Add the lemon sliced  up to the saucepan and cook it all together for for 15 min. So that it is all cooked up.  and put it onto a plate to cool.Now there should be some sauce still left in the pan, so slice the cooked potatoe and add it to the pan to get all that tasty sauce.Now cut up the chicken, potato and some grated mozzarella cheese and mash it up so that you can stuff it into the artichoke.",
          "Bake in oven at 350 for 20ish min."
        ]
      },
      "nl": {
        "title": "Gevuld Artisjok Hoofdgerecht",
        "subtitle": "Hoofdgerecht Gevulde Artisjok is een glutenvrij recept met 2 porties.",
        "description": "Hoofdgerecht Gevulde Artisjok is een glutenvrij recept met 2 porties. 18 mensen hebben dit recept geprobeerd en vonden het leuk. Een paar mensen vonden dit hoofdgerecht erg lekker. Van bereiding tot op het bord duurt dit recept ongeveer 1 uur.",
        "instructions": [
          "Trek de middelste bladeren van de artisjok uit elkaar",
          "Snij het midden zo af dat je het stekelige midden pakt",
          "Gebruik een lepel om dat allemaal eruit te halen, zodat alleen het midden leeg is",
          "Voeg een beetje citroensap toe om ervoor te zorgen dat het niet van kleur verandert",
          "Voeg artisjok toe aan kokend water",
          "Laat het 10 minuten koken, zodat het een beetje zacht wordt",
          "Afhalen",
          "Voeg koud water toe zodat het afkoelt",
          "Snijd de randen van de artisjok",
          "Zo maak je de vulling. Kook de aardappel, of doe hem in de magnetron om hem klaar te maken. (het hoeft alleen maar zacht te zijn) Voeg in een pan op middelhoog vuur de olijfolie, rozemarijn, ahornsiroop, geperste en fijngesneden knoflook en de kip toe.",
          "Voeg de in plakjes gesneden citroen toe aan de pan en kook alles samen gedurende 15 minuten. Zodat het allemaal gaar is.  en leg het op een bord om af te koelen. Er moet nu nog wat saus in de pan zitten, dus snijd de gekookte aardappel in plakjes en voeg deze toe aan de pan om een ​​heerlijke saus te krijgen. Snijd nu de kip, de aardappel en wat geraspte mozzarella in stukken en pureer het zodat je het in de artisjok kunt stoppen.",
          "Bak in de oven op 350 gedurende 20 minuten."
        ]
      },
      "fr": {
        "title": "Plat principal d'artichauts farcis",
        "subtitle": "Le plat principal aux artichauts farcis est une recette sans gluten...",
        "description": "Le plat principal aux artichauts farcis est une recette sans gluten de 2 portions. 18 personnes ont essayé et aimé cette recette. Quelques personnes ont vraiment aimé ce plat principal. De la préparation à l'assiette, cette recette prend environ 1 heure. Avec une note cuillère de 95%, ce plat est excellent.",
        "instructions": [
          "Séparez les feuilles centrales de l'artichaut",
          "Coupez le centre pour prendre le centre épineux",
          "Utilisez une cuillère pour retirer tout cela afin que seul le centre soit vide.",
          "Ajoutez un peu de jus de citron pour éviter qu'il ne change de couleur",
          "Ajouter l'artichaut à l'eau bouillante",
          "Laisser bouillir 10 minutes pour que ça devienne un peu mou",
          "Sortir",
          "Ajouter de l'eau froide pour que ça refroidisse",
          "Couper les bords de l'artichaut",
          "Comment faire la farce. Faire bouillir la pomme de terre ou la mettre au micro-ondes pour la cuire. (il faut juste qu'il soit tendre) Dans une casserole à feu moyen-vif, ajoutez l'huile d'olive, le romarin, le sirop d'érable, l'ail écrasé et finement émincé et le poulet.",
          "Ajoutez le citron coupé en tranches dans la casserole et faites cuire le tout pendant 15 min. Pour que tout soit cuit.  et mettez-le dans une assiette pour qu'il refroidisse.Maintenant, il devrait rester un peu de sauce dans la poêle, alors coupez la pomme de terre cuite et ajoutez-la à la poêle pour obtenir toute cette sauce savoureuse.Maintenant, coupez le poulet, la pomme de terre et un peu de fromage mozzarella râpé et écrasez-le pour pouvoir le farcir dans l'artichaut.",
          "Cuire au four à 350 pendant 20 minutes."
        ]
      }
    },
