    "translations": {
      "en": {
        "title": "Chicken Parmayonnaise",
        "subtitle": "Chicken Parmayonnaise is a main course that serves 6.",
        "description": "Chicken Parmayonnaise is a main course that serves 6. Not a lot of people made this recipe, and 2 would say it hit the spot. From preparation to the plate, this recipe takes about 45 minutes. If you have kosher salt and coarse pepper, herbs, mayonnaise, and a few other ingredients on hand, you can make it. It is a good option if you're following a gluten free diet.",
        "instructions": [
          "Oven to 375.Lightly pound breasts to uniform thickness ( not thin).",
          "Combine ingredients.",
          "Place chicken in baking dish.",
          "Spread mix evenly over chicken.",
          "Bake 25-30 minutes until top starts to brown."
        ]
      },
      "nl": {
        "title": "Kip Parmayonaise",
        "subtitle": "Kip-parmayonaise is een hoofdgerecht voor 6 personen.",
        "description": "Kip-parmayonaise is een hoofdgerecht voor 6 personen. Niet veel mensen hebben dit recept gemaakt, en 2 zouden zeggen dat het een schot in de roos was. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Als je koosjer zout en grove peper, kruiden, mayonaise en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het is een goede optie als je een glutenvrij dieet volgt.",
        "instructions": [
          "Oven op 375. De borsten lichtjes platdrukken tot een uniforme dikte (niet dun).",
          "Combineer ingrediënten.",
          "Leg de kip in de ovenschaal.",
          "Verdeel het mengsel gelijkmatig over de kip.",
          "Bak 25-30 minuten tot de bovenkant bruin begint te worden."
        ]
      },
      "fr": {
        "title": "Poulet Parmayonnaise",
        "subtitle": "Le poulet parmayonnaise est un plat principal pour 6 personnes.",
        "description": "Le poulet parmayonnaise est un plat principal pour 6 personnes. Peu de gens ont fait cette recette, et 2 diraient qu’elle a fait mouche. De la préparation à l'assiette, cette recette prend environ 45 minutes. Si vous avez du sel casher et du gros poivre, des herbes, de la mayonnaise et quelques autres ingrédients sous la main, vous pouvez le préparer. C'est une bonne option si vous suivez un régime sans gluten.",
        "instructions": [
          "Four à 375°. Piler légèrement les poitrines jusqu'à obtenir une épaisseur uniforme (pas fine).",
          "Mélanger les ingrédients.",
          "Placer le poulet dans un plat allant au four.",
          "Répartir uniformément le mélange sur le poulet.",
          "Cuire au four 25 à 30 minutes jusqu'à ce que le dessus commence à dorer."
        ]
      }
    },
