    "image": "images/spoonacular-639620.jpg",
    "isGlutenFree": false,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
