    "translations": {
      "en": {
        "title": "Classic New England Crab Cakes",
        "subtitle": "If you want to add more pescatarian and ketogenic recipes to your c...",
        "description": "If you want to add more pescatarian and ketogenic recipes to your collection, Classic New England Crab Cakes might be a recipe you should try. This recipe serves 6. A couple people really liked this hor d'oeuvre. A mixture of worcestershire sauce, celery, butter, and a handful of other ingredients are all it takes to make this recipe so delicious. From preparation to the plate, this recipe takes around 45 minutes. This score is good.",
        "instructions": [
          "Cook onion and celery in 4 tablespoons butter over moderately low heat, until tender and transfer to a bowl. Stir in crab and bread crumbs.",
          "In a small bowl whisk together mayonnaise, seafood seasoning, Worcestershire sauce, hot sauce, parsley, and salt and pepper to taste and stir into crab mixture until combined well.",
          "Line a baking sheet with wax paper. Form crab mixture into 6 flattened rounds. Chill crab cakes, covered with plastic wrap, at least 1 hour.",
          "Heat 1 tablespoon butter over moderate heat until foam subsides and cook half of crab cakes until golden brown, about 2 to 3 minutes on each side. Cook remaining cakes in remaining tablespoon butter in same manner."
        ]
      },
      "nl": {
        "title": "Klassieke krabkoekjes uit New England",
        "subtitle": "Als je meer pescatarische en ketogene recepten aan je verzameling w...",
        "description": "Als je meer pescatarische en ketogene recepten aan je verzameling wilt toevoegen, is Classic New England Crab Cakes misschien een recept dat je zou moeten proberen. Dit recept is voor 6 personen. Een paar mensen vonden dit hor d'oeuvre erg lekker. Een mengsel van worcestershiresaus, selderij, boter en een handvol andere ingrediënten is voldoende om dit recept zo heerlijk te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Dit cijfer is goed.",
        "instructions": [
          "Kook de ui en bleekselderij in 4 eetlepels boter op matig laag vuur tot ze gaar zijn en doe ze in een kom. Roer de krab en broodkruimels erdoor.",
          "Meng in een kleine kom mayonaise, zeevruchtenkruiden, Worcestershire-saus, hete saus, peterselie en zout en peper naar smaak en roer het krabmengsel erdoor tot alles goed gemengd is.",
          "Bekleed een bakplaat met vetvrij papier. Vorm het krabmengsel in 6 afgeplatte rondjes. Laat krabkoekjes, bedekt met plasticfolie, minimaal 1 uur afkoelen.",
          "Verhit 1 eetlepel boter op matig vuur tot het schuim afneemt en bak de helft van de crabcakes goudbruin, ongeveer 2 tot 3 minuten aan elke kant. Kook de resterende cakes in de resterende eetlepel boter op dezelfde manier."
        ]
      },
      "fr": {
        "title": "Gâteaux de crabe classiques de la Nouvelle-Angleterre",
        "subtitle": "Si vous souhaitez ajouter plus de recettes pescatariennes et cétogè...",
        "description": "Si vous souhaitez ajouter plus de recettes pescatariennes et cétogènes à votre collection, les galettes de crabe classiques de la Nouvelle-Angleterre pourraient être une recette que vous devriez essayer. Cette recette en sert 6. Quelques personnes ont vraiment aimé cet hor-d'œuvre. Un mélange de sauce Worcestershire, de céleri, de beurre et d'une poignée d'autres ingrédients suffit pour rendre cette recette si délicieuse. De la préparation à l'assiette, cette recette prend environ 45 minutes. Ce score est bon.",
        "instructions": [
          "Cuire l'oignon et le céleri dans 4 cuillères à soupe de beurre à feu moyen-doux, jusqu'à ce qu'ils soient tendres, puis transférer dans un bol. Incorporer le crabe et la chapelure.",
          "Dans un petit bol, fouetter ensemble la mayonnaise, l'assaisonnement pour fruits de mer, la sauce Worcestershire, la sauce piquante, le persil, le sel et le poivre au goût et incorporer au mélange de crabe jusqu'à ce que le tout soit bien mélangé.",
          "Tapisser une plaque à pâtisserie de papier ciré. Former le mélange de crabe en 6 rondelles aplaties. Réfrigérer les beignets de crabe recouverts d'une pellicule plastique pendant au moins 1 heure.",
          "Faites chauffer 1 cuillère à soupe de beurre à feu modéré jusqu'à ce que la mousse disparaisse et faites cuire la moitié des beignets de crabe jusqu'à ce qu'ils soient dorés, environ 2 à 3 minutes de chaque côté. Cuire le reste des gâteaux dans le reste de la cuillère à soupe de beurre de la même manière."
        ]
      }
    },
