    "translations": {
      "en": {
        "title": "Honeyed Bacon\" Baklava",
        "subtitle": "If you want to add more middl eastern recipes to your recipe box, H...",
        "description": "If you want to add more middl eastern recipes to your recipe box, Honeyed Bacon\" Baklava might be a recipe you should try. A mixture of walnuts, sugar, ground cinnamon, and a handful of other ingredients are all it takes to make this recipe so tasty. 11 person were glad they tried this recipe. From preparation to the plate, this recipe takes around 45 minutes. Users who liked this recipe also liked Bacon Baklava, Honeyed Chicken, and Honeyed Olives.",
        "instructions": [
          "In large bowl of food processor, add walnuts, bacon, sugar, and cinnamon. Pulse until walnuts and bacon are chopped; set aside. (Be sure to fry the bacon to a crispy stage. Then it will chop up finely and evenly.)",
          "Cut phyllo into 13\" by 9\" rectangles. In greased 13\" by 9\" baking dish, place 1 phyllo sheet; brush with melted butter. Repeat with phyllo and butter to make 5 more layers, overlapping any small strips of phyllo to make rectangles, if necessary.",
          "Over phyllo in baking dish, sprinkle 1 cup walnut mixture.",
          "Repeat steps 2 and 3 to make 3 more layers (4 layers total).",
          "Place remaining phyllo on top of last walnut layer; brush with butter.",
          "With sharp knife, cut just halfway through layers in triangle or diamond pattern.",
          "Bake in 300 degree oven for 1 hour and 25 minutes or until top is golden brown.",
          "In small saucepan over medium-low heat, heat honey until hot but not boiling. Evenly spoon hot honey over hot baklava.",
          "Cool Baklava in dish on wire rack at least 1 hour; cover with foil and let stand at room temperature until serving.",
          "To serve, finish cutting, with a sharp knife, through layers to make triangles or diamonds."
        ]
      },
      "nl": {
        "title": "Honingspek\" Baklava",
        "subtitle": "Als je meer recepten uit het Midden-Oosten aan je receptendoos wilt...",
        "description": "Als je meer recepten uit het Midden-Oosten aan je receptendoos wilt toevoegen, is Baklava met honingbacon misschien een recept dat je zou moeten proberen. Een mengsel van walnoten, suiker, gemalen kaneel en een handvol andere ingrediënten is alles wat nodig is om dit recept zo lekker te maken. 11 personen waren blij dat ze dit recept hebben geprobeerd. Van voorbereiding tot op het bord, Dit recept duurt ongeveer 45 minuten. Gebruikers die dit recept lekker vonden, hielden ook van Bacon Baklava, Honeyed Chicken en Honeyed Olives.",
        "instructions": [
          "Voeg in een grote kom van de keukenmachine walnoten, spek, suiker en kaneel toe. Pulseer tot walnoten en spek zijn gehakt; opzij zetten. (Zorg ervoor dat je het spek knapperig bakt. Dan wordt het fijn en gelijkmatig gehakt.)",
          "Snijd filodeeg in rechthoeken van 13 bij 9 inch. Plaats in een ingevette ovenschaal van 13 bij 9 inch 1 filodeegvel; bestrijk met gesmolten boter. Herhaal dit met filodeeg en boter om nog 5 lagen te maken, waarbij u indien nodig kleine reepjes filodeeg overlapt om rechthoeken te maken.",
          "Strooi 1 kop walnotenmengsel over de filodeeg in de ovenschaal.",
          "Herhaal stap 2 en 3 om nog 3 lagen te maken (4 lagen in totaal).",
          "Plaats de resterende filodeeg bovenop de laatste walnootlaag; bestrijk met boter.",
          "Snijd met een scherp mes tot halverwege de lagen in een driehoek- of ruitpatroon.",
          "Bak in een oven van 300 graden gedurende 1 uur en 25 minuten of tot de bovenkant goudbruin is.",
          "Verhit de honing in een kleine pan op middelhoog vuur tot hij heet is, maar niet kookt. Schep gelijkmatig hete honing over hete baklava.",
          "Baklava in de schaal op een rooster minimaal 1 uur laten afkoelen; dek af met folie en laat op kamertemperatuur staan ​​tot het serveren.",
          "Om te serveren, snijdt u met een scherp mes door de lagen heen om driehoeken of diamanten te maken."
        ]
      },
      "fr": {
        "title": "Baklava au bacon au miel",
        "subtitle": "Si vous souhaitez ajouter d'autres recettes du Moyen-Orient à votre...",
        "description": "Si vous souhaitez ajouter d'autres recettes du Moyen-Orient à votre boîte de recettes, le Baklava au bacon et au miel pourrait être une recette que vous devriez essayer. cette recette prend environ 45 minutes. Les utilisateurs qui ont aimé cette recette ont également aimé le Bacon Baklava, le Poulet au Miel et les Olives au Miel.",
        "instructions": [
          "Dans un grand bol du robot culinaire, ajouter les noix, le bacon, le sucre et la cannelle. Pulser jusqu'à ce que les noix et le bacon soient hachés; annuler. (Assurez-vous de faire frire le bacon jusqu'à ce qu'il soit croustillant. Il sera ensuite haché finement et uniformément.)",
          "Couper la pâte phyllo en rectangles de 13\" sur 9\". Dans un plat allant au four graissé de 13\" sur 9\", placer 1 feuille de pâte phyllo; badigeonner de beurre fondu. Répétez avec de la pâte phyllo et du beurre pour faire 5 couches supplémentaires, en superposant les petites bandes de pâte phyllo pour former des rectangles, si nécessaire.",
          "Sur la pâte phyllo dans un plat allant au four, saupoudrer 1 tasse du mélange de noix.",
          "Répétez les étapes 2 et 3 pour créer 3 couches supplémentaires (4 couches au total).",
          "Placer le reste de la pâte phyllo sur la dernière couche de noix; badigeonner de beurre.",
          "Avec un couteau bien aiguisé, coupez juste à moitié les couches en forme de triangle ou de losange.",
          "Cuire au four à 300 degrés pendant 1 heure et 25 minutes ou jusqu'à ce que le dessus soit doré.",
          "Dans une petite casserole à feu moyen-doux, chauffer le miel jusqu'à ce qu'il soit chaud mais pas bouillant. Verser uniformément le miel chaud sur le baklava chaud.",
          "Refroidir le Baklava dans un plat sur une grille pendant au moins 1 heure ; couvrir de papier d'aluminium et laisser reposer à température ambiante jusqu'au moment de servir.",
          "Pour servir, finir de découper, avec un couteau bien aiguisé, en couches pour former des triangles ou des losanges."
        ]
      }
    },
