    "isGlutenFree": false,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Vegetarian Tostadas With Spicy Black Beans (+gluten free)",
        "subtitle": "If you want to add more gluten free and lacto ovo vegetarian recipe...",
        "description": "If you want to add more gluten free and lacto ovo vegetarian recipes to your recipe box, Vegetarian Tostadas With Spicy Black Beans (+gluten free) might be a recipe you should try. From preparation to the plate, this recipe takes around 45 minutes. 3 people were glad they tried this recipe. A mixture of chiles in adobo sauce, cherry tomatoes, feta cheese, and a handful of other ingredients are all it takes to make this recipe so tasty. It is an affordable recipe for fans of Mexican food. This score is solid. Users who liked this recipe also liked Vegetarian Tostadas With Spicy Black Beans (+gluten free), Gluten Free Cashew Chicken (Spicy, Vegetarian, Nut-Free, & Soy-Free Options), and Gluten Free Chicken Black Beans and Rice.",
        "instructions": [
          "Heat a large saute pan on medium high heat.",
          "Saute your onions and garlic in olive oil for 2-3 minutes.",
          "Place your balck beans (BB) in a microwavble safe container and add the sauted onions and garilc to the BB.",
          "Add the diced chiles in adobo sauce to the BB.",
          "Sprinkle in some dried basil and garilc sea salt. Stir and microwave for 2 minutes, using a potato masher mash the warm BB to your desired consistency and return to the microwave for 1 minute.",
          "Meanwhile take a paper towel and using the same saute pan wipe out any excess oil or browning from the onions. Spray with cooking oil and on high heat, toast your tortillas until crsipy anywhere from 5 to 10 minutes.",
          "Assemble your tostadas by placing the beans on top, sprinkle with feta, top with spinach, sliced cherry tomatoes, dollop of sour cream and sprinkle with more feta and salsa"
        ]
      },
      "nl": {
        "title": "Vegetarische Tostadas Met Pittige Zwarte Bonen (+glutenvrij)",
        "subtitle": "Als je meer glutenvrije en lacto ovo-vegetarische recepten aan je r...",
        "description": "Als je meer glutenvrije en lacto ovo-vegetarische recepten aan je receptendoos wilt toevoegen, is Vegetarische Tostadas met Pittige Zwarte Bonen (+glutenvrij) wellicht een recept dat je moet proberen. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. 3 mensen waren blij dat ze dit recept probeerden. Een mengsel van chilipepers in adobosaus, kerstomaatjes, fetakaas en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Het is een betaalbaar recept voor liefhebbers van Mexicaans eten. Deze score is solide. Gebruikers die dit recept lekker vonden, hielden ook van vegetarische tostadas met pittige zwarte bonen (+glutenvrij), glutenvrije cashewkip (pikante, vegetarische, notenvrije en sojavrije opties) en glutenvrije kip, zwarte bonen en rijst.",
        "instructions": [
          "Verhit een grote koekenpan op middelhoog vuur.",
          "Fruit de uien en knoflook 2-3 minuten in olijfolie.",
          "Plaats uw zwarte bonen (BB) in een magnetronbestendige container en voeg de gebakken uien en knoflook toe aan de BB.",
          "Voeg de in blokjes gesneden chilipepers in adobosaus toe aan de BB.",
          "Strooi er wat gedroogde basilicum en knoflookzeezout over. Roer en magnetron gedurende 2 minuten, gebruik een aardappelstamper en pureer de warme BB tot de gewenste consistentie en zet het terug in de magnetron gedurende 1 minuut.",
          "Neem ondertussen een papieren handdoek en gebruik dezelfde koekenpan om overtollige olie of bruin worden van de uien te verwijderen. Bestrijk ze met bakolie en rooster je tortilla's op hoog vuur in 5 tot 10 minuten knapperig.",
          "Stel je tostadas samen door de bonen erop te leggen, bestrooi met feta, top met spinazie, gesneden kerstomaatjes, klodder zure room en bestrooi met meer feta en salsa"
        ]
      },
      "fr": {
        "title": "Tostadas végétariennes aux haricots noirs épicés (+ sans gluten)",
        "subtitle": "Si vous souhaitez ajouter plus de recettes végétariennes sans glute...",
        "description": "Si vous souhaitez ajouter plus de recettes végétariennes sans gluten et lacto ovo à votre boîte de recettes, les tostadas végétariennes aux haricots noirs épicés (+ sans gluten) pourraient être une recette que vous devriez essayer. De la préparation à l'assiette, cette recette prend environ 45 minutes. 3 personnes étaient contentes d'avoir essayé cette recette. Un mélange de piments à la sauce adobo, de tomates cerises, de fromage feta et d'une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. C'est une recette abordable pour les amateurs de cuisine mexicaine. Ce score est solide. Les utilisateurs qui ont aimé cette recette ont également aimé Tostadas végétariennes aux haricots noirs épicés (+ sans gluten), Poulet aux noix de cajou sans gluten (options épicées, végétariennes, sans noix et sans soja) et Poulet sans gluten, haricots noirs et riz.",
        "instructions": [
          "Faites chauffer une grande sauteuse à feu moyen-vif.",
          "Faites revenir vos oignons et votre ail dans l'huile d'olive pendant 2-3 minutes.",
          "Placez vos haricots noirs (BB) dans un récipient allant au micro-ondes et ajoutez les oignons sautés et l'ail au BB.",
          "Ajouter les piments coupés en dés dans la sauce adobo au BB.",
          "Saupoudrer de basilic séché et de sel marin d'ail. Remuer et passer au micro-ondes pendant 2 minutes, à l'aide d'un presse-purée, écraser le BB chaud jusqu'à obtenir la consistance souhaitée et remettre au micro-ondes pendant 1 minute.",
          "Pendant ce temps, prenez une serviette en papier et, à l'aide de la même sauteuse, essuyez tout excès d'huile ou brunissement des oignons. Vaporisez d'huile de cuisson et à feu vif, faites griller vos tortillas jusqu'à ce qu'elles soient croustillantes, de 5 à 10 minutes.",
          "Assemblez vos tostadas en plaçant les haricots dessus, saupoudrez de feta, garnissez d'épinards, de tranches de tomates cerises, d'une cuillerée de crème sure et saupoudrez de feta et de salsa."
        ]
      }
    },
