    "image": "images/spoonacular-635040.jpg",
    "isGlutenFree": true,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
