    "translations": {
      "en": {
        "title": "Bittersweet Chocolate Ice Cream",
        "subtitle": "Bittersweet Chocolate Ice Cream is a gluten free, lacto ovo vegetar...",
        "description": "Bittersweet Chocolate Ice Cream is a gluten free, lacto ovo vegetarian, and primal recipe with 2 servings. 68 people have tried and liked this recipe. A mixture of half& half, heavy whipping cream, vanillan extract, and a handful of other ingredients are all it takes to make this recipe so flavorful. From preparation to the plate, this recipe takes roughly 45 minutes. It will be a hit at your Summer event. If you like this recipe, you might also like recipes such as Bittersweet Chocolate Ice Cream, Chocolate Pound Cake with Strawberry Ice Cream and Bittersweet Chocolate Sauce, and Bittersweet Molten Chocolate Cakes with Coffee Ice Cream.",
        "instructions": [
          "Prep your ice cream maker according to the manufacturers directions.In a medium sauce pan, heat the half & half until warm- not hot.In a bowl, whisk the egg yolks until blended.",
          "Add the sugar and about 1/2 of the warm half and half. Stir to combine well and add the mixture back to the saucepan.",
          "Whisking briskly while combining.Cook over medium heat until the mixture coats the back of a silicone spatula (about 10-12 minutes).",
          "Remove from heat and add the chocolate and coffee, stir to melt and combine thoroughly.",
          "Place the pan with the custard in an ice bath to cool, stirring occasionally, until it reaches room temperature.",
          "Add the whipping cream and vanilla",
          "Pour into another container and chill until cold -several hours-or you are ready pour into the ice cream maker.Freeze in the ice cream maker according to the manufacturers directions. Makes about a quart."
        ]
      },
      "nl": {
        "title": "Bitterzoet chocolade-ijs",
        "subtitle": "Bitterzoet chocolade-ijs is een glutenvrij, lacto-ovo-vegetarisch e...",
        "description": "Bitterzoet chocolade-ijs is een glutenvrij, lacto-ovo-vegetarisch en oerrecept met 2 porties. 68 mensen hebben dit recept geprobeerd en vonden het leuk. Een mengsel van half en half zware slagroom, vanille-extract en een handvol andere ingrediënten is alles wat nodig is om dit recept zo smaakvol te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Het zal een hit zijn op uw zomerevenement. Als je dit recept lekker vindt, vind je misschien ook recepten leuk zoals bitterzoet chocolade-ijs, chocoladetaart met aardbeienijs en bitterzoete chocoladesaus, en bitterzoete gesmolten chocoladetaarten met koffie-ijs.",
        "instructions": [
          "Bereid uw ijsmachine voor volgens de aanwijzingen van de fabrikant. Verhit de helft en de helft in een middelgrote pan tot het warm is (niet heet). Klop de eidooiers in een kom tot ze gemengd zijn.",
          "Voeg de suiker en ongeveer de helft van de warme helft en de helft toe. Roer goed door elkaar en doe het mengsel terug in de pan.",
          "Stevig kloppen terwijl je mengt. Kook op middelhoog vuur tot het mengsel de achterkant van een siliconen spatel bedekt (ongeveer 10-12 minuten).",
          "Haal van het vuur en voeg de chocolade en koffie toe, roer om te smelten en meng goed.",
          "Zet de pan met de custard in een ijsbad om af te koelen, af en toe roerend, tot het op kamertemperatuur is.",
          "Voeg de slagroom en vanille toe",
          "Giet het mengsel in een ander bakje en laat het afkoelen tot het koud is (enkele uren) of je bent klaar. Giet het in de ijsmachine. Vries het in de ijsmachine in volgens de aanwijzingen van de fabrikant. Maakt ongeveer een kwart."
        ]
      },
      "fr": {
        "title": "Glace au chocolat aigre-doux",
        "subtitle": "La crème glacée au chocolat doux-amer est une recette sans gluten,...",
        "description": "La crème glacée au chocolat doux-amer est une recette sans gluten, lacto ovo végétarienne et primale avec 2 portions. 68 personnes ont essayé et aimé cette recette. Un mélange moitié-moitié, de la crème fouettée épaisse, de l'extrait de vanille et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. De la préparation à l'assiette, cette recette prend environ 45 minutes. Ce sera un succès lors de votre événement d'été. Si vous aimez cette recette, vous aimerez peut-être également des recettes telles que Glace au chocolat aigre-doux, Quatre-quarts au chocolat avec glace à la fraise et sauce au chocolat aigre-doux, et Gâteaux au chocolat fondu aigre-doux avec glace au café.",
        "instructions": [
          "Préparez votre sorbetière selon les instructions du fabricant. Dans une casserole moyenne, faites chauffer la moitié-moitié jusqu'à ce qu'elle soit chaude, pas chaude. Dans un bol, fouettez les jaunes d'œufs jusqu'à ce que le mélange soit homogène.",
          "Ajouter le sucre et environ la moitié de la moitié-moitié chaude. Remuer pour bien mélanger et remettre le mélange dans la casserole.",
          "Fouetter vivement tout en mélangeant. Cuire à feu moyen jusqu'à ce que le mélange recouvre le dos d'une spatule en silicone (environ 10 à 12 minutes).",
          "Retirer du feu et ajouter le chocolat et le café, remuer pour fondre et bien mélanger.",
          "Placez la casserole avec la crème anglaise dans un bain de glace pour qu'elle refroidisse, en remuant de temps en temps, jusqu'à ce qu'elle atteigne la température ambiante.",
          "Ajouter la crème fouettée et la vanille",
          "Versez dans un autre récipient et réfrigérez jusqu'à ce qu'il soit froid – plusieurs heures – ou vous êtes prêt à verser dans la sorbetière. Congelez dans la sorbetière selon les instructions du fabricant. Cela fait environ un litre."
        ]
      }
    },
