    "translations": {
      "en": {
        "title": "One Soup, Two Ways: Chunky Vegetables and Cream Of Vegetables",
        "subtitle": "The recipe One Soup, Two Ways: Chunky Vegetables and Cream Of Veget...",
        "description": "The recipe One Soup, Two Ways: Chunky Vegetables and Cream Of Vegetables can be made in around 45 minutes. It will be a hit at your Autumn event. 2 people were glad they tried this recipe. A mixture of beans, cooking cream, carrots, and a handful of other ingredients are all it takes to make this recipe so tasty. If you like this recipe, you might also like recipes such as One Soup, Two Ways: Chunky Vegetables and Cream Of Vegetables, Chunky Vegetables with Fusilli, and Chunky pasta sauce with more vegetables than meat.",
        "instructions": [
          "Heat olive oil over medium low heat in a soup pot (big enough to hold everything you have) and throw in garlic, onions, carrots and celery.",
          "Stir around a bit, add the salt and cover.",
          "Let sweat for about 10 minutes.",
          "Add the tomato puree and corn, stir, let cook for a few minutes.",
          "Then add the broth, turn heat up to maximum and bring to a boil.",
          "Add the beans. Season with dried herbs.",
          "Transfer half of the chunky soup into another soup pot.",
          "Whiz everything up with a hand-held blender, or in a blender. Then use a sieve, and \"filter\" the soup.",
          "Bring back to a boil, add  cream, turmeric, curry powder, cayenne pepper and stir well."
        ]
      },
      "nl": {
        "title": "Eén soep, twee manieren: dikke groenten en groentecrème",
        "subtitle": "Het recept Eén soep, twee manieren: dikke groenten en groentecrème...",
        "description": "Het recept Eén soep, twee manieren: dikke groenten en groentecrème is in ongeveer 45 minuten te maken. Het zal een hit zijn op uw herfstevenement. 2 mensen waren blij dat ze dit recept probeerden. Een mengsel van bonen, kookroom, wortelen en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Als je dit recept lekker vindt, vind je misschien ook recepten leuk zoals Eén soep, Twee manieren: dikke groenten en crème van groenten, Dikke groenten met Fusilli en Dikke pastasaus met meer groenten dan vlees.",
        "instructions": [
          "Verhit olijfolie op middelhoog vuur in een soeppan (groot genoeg voor alles wat je hebt) en doe de knoflook, uien, wortels en selderij erbij.",
          "Roer een beetje rond, voeg het zout toe en dek af.",
          "Laat ongeveer 10 minuten zweten.",
          "Voeg de tomatenpuree en de maïs toe, roer en laat een paar minuten koken.",
          "Voeg vervolgens de bouillon toe, zet het vuur maximaal en breng aan de kook.",
          "Voeg de bonen toe. Breng op smaak met gedroogde kruiden.",
          "Doe de helft van de dikke soep in een andere soeppan.",
          "Pureer alles met een staafmixer of in een blender. Gebruik dan een zeef en \"filter\" de soep.",
          "Breng opnieuw aan de kook, voeg room, kurkuma, kerriepoeder, cayennepeper toe en roer goed."
        ]
      },
      "fr": {
        "title": "Une soupe, deux façons : légumes en morceaux et crème de légumes",
        "subtitle": "La recette Une soupe, deux façons : gros légumes et crème de légume...",
        "description": "La recette Une soupe, deux façons : gros légumes et crème de légumes peut être préparée en 45 minutes environ. Ce sera un succès lors de votre événement d'automne. 2 personnes étaient contentes d'avoir essayé cette recette. Un mélange de haricots, de crème de cuisson, de carottes et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que Une soupe, deux façons : légumes en morceaux et crème de légumes, Légumes en morceaux avec fusilli et Sauce pour pâtes en morceaux avec plus de légumes que de viande.",
        "instructions": [
          "Faites chauffer l'huile d'olive à feu moyen-doux dans une marmite (assez grande pour contenir tout ce que vous avez) et ajoutez-y l'ail, les oignons, les carottes et le céleri.",
          "Remuez un peu, ajoutez le sel et couvrez.",
          "Laissez suer environ 10 minutes.",
          "Ajoutez le concentré de tomates et le maïs, remuez, laissez cuire quelques minutes.",
          "Ajoutez ensuite le bouillon, augmentez le feu au maximum et portez à ébullition.",
          "Ajoutez les haricots. Assaisonner avec des herbes séchées.",
          "Transférez la moitié de la soupe en morceaux dans une autre marmite.",
          "Mixez le tout au mixeur plongeant ou au mixeur. Utilisez ensuite une passoire, et « filtrez » la soupe.",
          "Ramenez à ébullition, ajoutez la crème, le curcuma, la poudre de curry, le poivre de Cayenne et remuez bien."
        ]
      }
    },
