      "en": {
        "title": "Apple Cake",
        "subtitle": "The recipe Apple Cake can be made in approximately 45 minutes.",
        "description": "The recipe Apple Cake can be made in approximately 45 minutes. This recipe is liked by 2 foodies and cooks. It works well as a dessert. If you have apples preferably jonathan, salt, vanilla, and a few other ingredients on hand, you can make it. It is a good option if you're following a dairy free and lacto ovo vegetarian diet.",
        "instructions": [
          "Preheat oven to 350F degrees.In a large bowl, mix together apples, oil, sugar, eggs and walnuts by hand.",
          "Mix well then set aside.In a separate bowl, mix flour, baking soda, salt, vanilla and cinnamon",
          "Mix well then add to the apple mixture. The batter will be thick.",
          "Pour into ungreased 13x9 baking pan, and bake for one hour or until done."
        ]
      },
      "nl": {
        "title": "Appeltaart",
        "subtitle": "Het recept Appeltaart maak je in ongeveer 45 minuten.",
        "description": "Het recept Appeltaart maak je in ongeveer 45 minuten. Dit recept is geliefd bij 2 foodies en koks. Het werkt goed als dessert. Als je appels bij de hand hebt, bij voorkeur jonathan, zout, vanille en een paar andere ingrediënten, kun je het maken. Het is een goede optie als je een zuivelvrij en lacto-ovo-vegetarisch dieet volgt.",
        "instructions": [
          "Verwarm de oven voor op 350F graden. Meng in een grote kom appels, olie, suiker, eieren en walnoten met de hand.",
          "Meng goed en zet opzij. Meng in een aparte kom de bloem, bakpoeder, zout, vanille en kaneel",
          "Meng goed en voeg dan toe aan het appelmengsel. Het beslag zal dik zijn.",
          "Giet het in een niet-ingevette bakvorm van 13x9 en bak een uur of tot het klaar is."
        ]
      },
      "fr": {
        "title": "Gâteau aux pommes",
        "subtitle": "La recette Gâteau aux pommes peut être réalisée en 45 minutes environ.",
        "description": "La recette Gâteau aux pommes peut être réalisée en 45 minutes environ. Cette recette est appréciée par 2 gourmands et cuisiniers. Cela fonctionne bien comme dessert. Si vous avez des pommes de préférence Jonathan, du sel, de la vanille et quelques autres ingrédients sous la main, vous pouvez le préparer. C'est une bonne option si vous suivez un régime végétarien sans produits laitiers et lacto-ovo.",
        "instructions": [
          "Préchauffer le four à 350F degrés. Dans un grand bol, mélanger à la main les pommes, l'huile, le sucre, les œufs et les noix.",
          "Bien mélanger puis réserver. Dans un autre bol, mélanger la farine, le bicarbonate de soude, le sel, la vanille et la cannelle.",
          "Bien mélanger puis ajouter au mélange de pommes. La pâte sera épaisse.",
          "Verser dans un moule 13x9 non graissé et cuire au four pendant une heure ou jusqu'à ce qu'il soit cuit."
        ]
      }
