    "translations": {
      "en": {
        "title": "Healthy Vegan Red Velvet Brownies",
        "subtitle": "Healthy Vegan Red Velvet Brownies is a dessert that serves 8.",
        "description": "Healthy Vegan Red Velvet Brownies is a dessert that serves 8. Watching your figure? A mixture of baking soda, salt, ground flaxseed, and a handful of other ingredients are all it takes to make this recipe so tasty. 91 person found this recipe to be scrumptious and satisfying. A few people really liked this American dish. It is perfect for valentin day. From preparation to the plate, this recipe takes roughly 45 minutes.",
        "instructions": [
          "Preheat oven to 350 F.Spray an 8x8 inch pan with cooking spray. Set aside.In a food processor, puree kidney beans and beets.",
          "Transfer to a large bowl.",
          "Add remaining ingredients and mix by hand until smooth and fully combined.Fold batter into the greased pan.",
          "Bake for 35-40 minutes, turning the pan halfway through.When the brownies are done, test them with a toothpick. You want some batter to cling to the toothpick. Do not over bake.",
          "Let cool completely. Refrigerate for one hour.",
          "Cut into squares or use cookie cutters to make heart shapes."
        ]
      },
      "nl": {
        "title": "Gezonde veganistische roodfluwelen brownies",
        "subtitle": "Healthy Vegan Red Velvet Brownies is een dessert voor 8 personen.",
        "description": "Healthy Vegan Red Velvet Brownies is een dessert voor 8 personen. Op je figuur letten? Een mengsel van zuiveringszout, zout, gemalen lijnzaad en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. 91 personen vonden dit recept heerlijk en bevredigend. Een paar mensen vonden dit Amerikaanse gerecht erg lekker. Het is perfect voor Valentijnsdag. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Verwarm de oven voor op 350 F. Spuit een pan van 8x8 inch met kookspray. Zet opzij. Pureer de bruine bonen en bieten in een keukenmachine.",
          "Breng over naar een grote kom.",
          "Voeg de resterende ingrediënten toe en meng met de hand tot een gladde massa en volledig gecombineerd is. Vouw het beslag in de ingevette pan.",
          "Bak gedurende 35-40 minuten en draai de pan halverwege. Als de brownies klaar zijn, test je ze met een tandenstoker. Je wilt dat er wat beslag aan de tandenstoker blijft plakken. Bak niet te lang.",
          "Laat volledig afkoelen. Zet een uur in de koelkast.",
          "Snijd in vierkanten of gebruik koekjesvormers om hartvormen te maken."
        ]
      },
      "fr": {
        "title": "Brownies végétaliens sains au velours rouge",
        "subtitle": "Les brownies végétaliens sains au velours rouge sont un dessert pou...",
        "description": "Les brownies végétaliens sains au velours rouge sont un dessert pour 8 personnes. Vous surveillez votre silhouette ? Un mélange de bicarbonate de soude, de sel, de graines de lin moulues et d’une poignée d’autres ingrédients suffisent pour rendre cette recette si savoureuse. 91 personnes ont trouvé cette recette délicieuse et satisfaisante. Quelques personnes ont vraiment aimé ce plat américain. C'est parfait pour la Saint-Valentin. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Préchauffer le four à 350 F. Vaporiser une poêle de 8 x 8 pouces avec un enduit à cuisson. Réserver. Au robot culinaire, réduire en purée les haricots rouges et les betteraves.",
          "Transférer dans un grand bol.",
          "Ajouter le reste des ingrédients et mélanger à la main jusqu'à consistance lisse et bien mélangée. Incorporer la pâte dans le moule graissé.",
          "Cuire au four pendant 35 à 40 minutes en retournant le moule à mi-cuisson. Lorsque les brownies sont cuits, testez-les avec un cure-dent. Vous voulez qu’un peu de pâte adhère au cure-dent. Ne faites pas trop cuire.",
          "Laissez refroidir complètement. Réfrigérer une heure.",
          "Coupez en carrés ou utilisez des emporte-pièces pour créer des formes de cœur."
        ]
      }
    },
