    "translations": {
      "en": {
        "title": "Corn Chowder with Potatoes, Poblanos, and Smoked Gouda",
        "subtitle": "Corn Chowder with Potatoes, Poblanos, and Smoked Gouda might be a g...",
        "description": "Corn Chowder with Potatoes, Poblanos, and Smoked Gouda might be a good recipe to expand your hor d'oeuvre recipe box. This recipe serves 6. A few people made this recipe, and 22 would say it hit the spot. From preparation to the plate, this recipe takes around 45 minutes. A mixture of potatoes, half-and-half, poblano chiles, and a handful of other ingredients are all it takes to make this recipe so tasty. It is a good option if you're following a gluten free and lacto ovo vegetarian diet.",
        "instructions": [
          "In a large saut pan, melt the butter over medium heat and saut the onion for about 10 minutes, or until lightly browned.",
          "Transfer the onion to a 7-quart slow cooker and add the potatoes, bay leaf, thyme, and water. Cover and cook on LOW for about 4 hours, or until the potatoes are tender.Mash some of the potatoes against the inside of the cooker or use a handheld immersion blender to puree a small amount of potato and thicken the soup slightly.",
          "Add the corn, chiles, half-and-half, and  cup of the cheddar.",
          "Add the salt to taste and continue cooking for 20 to 30 minutes, or just until all the ingredients are hot.Ladle the soup into bowls and garnish each bowl with the remaining cheddar and chopped chives."
        ]
      },
      "nl": {
        "title": "Maïssoep met Aardappelen, Poblanos en Gerookte Gouda",
        "subtitle": "Maïssoep met Aardappelen, Poblanos en Gerookte Gouda is misschien e...",
        "description": "Maïssoep met Aardappelen, Poblanos en Gerookte Gouda is misschien een goed recept om je hor d'oeuvre-receptendoos uit te breiden. Dit recept is voor zes personen. Een paar mensen hebben dit recept gemaakt, en 22 zouden zeggen dat het een schot in de roos was. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Een mengsel van aardappelen, half en half, poblano chilipepers en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Het is een goede optie als je een glutenvrij en lacto-ovo-vegetarisch dieet volgt.",
        "instructions": [
          "Smelt de boter in een grote koekenpan op middelhoog vuur en bak de ui ongeveer 10 minuten, of tot hij lichtbruin is.",
          "Breng de ui over naar een slowcooker van 7 liter en voeg de aardappelen, het laurierblad, de tijm en het water toe. Dek af en kook op LAAG gedurende ongeveer 4 uur, of tot de aardappelen gaar zijn. Pureer een deel van de aardappelen tegen de binnenkant van het fornuis of gebruik een staafmixer om een ​​kleine hoeveelheid aardappel te pureren en de soep iets dikker te maken.",
          "Voeg de maïs, chilipepers, half en half en een kopje cheddar toe.",
          "Voeg het zout naar smaak toe en laat 20 tot 30 minuten koken, of totdat alle ingrediënten heet zijn. Schep de soep in kommen en garneer elke kom met de overgebleven cheddar en gehakte bieslook."
        ]
      },
      "fr": {
        "title": "Chaudrée de maïs avec pommes de terre, poblanos et gouda fumé",
        "subtitle": "La chaudrée de maïs avec pommes de terre, poblanos et gouda fumé po...",
        "description": "La chaudrée de maïs avec pommes de terre, poblanos et gouda fumé pourrait être une bonne recette pour élargir votre boîte de recettes de hors-d'œuvre. Cette recette en sert 6. Quelques personnes ont fait cette recette, et 22 diraient qu'elle a fait mouche. De la préparation à l'assiette, cette recette prend environ 45 minutes. Un mélange de pommes de terre, moitié-moitié, de piments poblano et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. C'est une bonne option si vous suivez un régime végétarien sans gluten et lacto ovo.",
        "instructions": [
          "Dans une grande sauteuse, faire fondre le beurre à feu moyen et faire revenir l'oignon pendant environ 10 minutes ou jusqu'à ce qu'il soit légèrement doré.",
          "Transférez l'oignon dans une mijoteuse de 7 litres et ajoutez les pommes de terre, le laurier, le thym et l'eau. Couvrir et cuire à feu doux pendant environ 4 heures, ou jusqu'à ce que les pommes de terre soient tendres. Écrasez quelques pommes de terre contre l'intérieur de la cuisinière ou utilisez un mélangeur à immersion pour réduire en purée une petite quantité de pomme de terre et épaissir légèrement la soupe.",
          "Ajouter le maïs, les piments, moitié-moitié et une tasse de cheddar.",
          "Ajoutez du sel au goût et poursuivez la cuisson pendant 20 à 30 minutes, ou jusqu'à ce que tous les ingrédients soient chauds. Versez la soupe dans des bols et garnissez chaque bol avec le reste du cheddar et de la ciboulette hachée."
        ]
      }
    },
