    "translations": {
      "en": {
        "title": "Curious George's Gluten-Free Banana Nut Bread",
        "subtitle": "Curious George's Gluten-Free Banana Nut Bread might be just the bre...",
        "description": "Curious George's Gluten-Free Banana Nut Bread might be just the breakfast you are searching for. Watching your figure? This recipe serves 8. 3 people were glad they tried this recipe. A mixture of lemon juice, butter, very browned bananas, and a handful of other ingredients are all it takes to make this recipe so scrumptious. From preparation to the plate, this recipe takes around 45 minutes.",
        "instructions": [
          "Preheat oven to 35",
          "Grease a loaf pan and set aside.",
          "Combine the flour, baking powder and salt in a bowl and set aside.",
          "Cream the shortening, butter and sugar together.",
          "Add the banana, lemon and eggs and beat to incorporate.",
          "Slowly add flour mixture and beat to incorporate.",
          "If using nuts, toss them loosely on a cookie sheet and toast for about 4 minutes, checking every minute, until slightly brown.  Toss them into batter and stir in.",
          "Pour batter into prepared pan and press down with a spatula to flatten.",
          "Bake for 75  90 minutes or until the top is brown and the bread gives a little to the touch."
        ]
      },
      "nl": {
        "title": "Curious George's glutenvrij bananen-notenbrood",
        "subtitle": "Curious George's glutenvrije bananen-notenbrood is misschien wel pr...",
        "description": "Curious George's glutenvrije bananen-notenbrood is misschien wel precies het ontbijt waar u naar op zoek bent. Op je figuur letten? Dit recept is voor 8 personen. 3 mensen waren blij dat ze dit recept probeerden. Een mengsel van citroensap, boter, zeer gebruinde bananen en een handvol andere ingrediënten is alles wat nodig is om dit recept zo heerlijk te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Verwarm de oven voor op 35",
          "Vet een broodvorm in en zet opzij.",
          "Meng de bloem, het bakpoeder en het zout in een kom en zet opzij.",
          "Meng het bakvet, de boter en de suiker door elkaar.",
          "Voeg de banaan, citroen en eieren toe en klop om te verwerken.",
          "Voeg langzaam het bloemmengsel toe en klop het op.",
          "Als u noten gebruikt, gooi ze dan losjes op een bakplaat en rooster ze ongeveer 4 minuten, controleer elke minuut, tot ze lichtbruin zijn.  Gooi ze door het beslag en roer erdoor.",
          "Giet het beslag in de voorbereide pan en druk het aan met een spatel om het plat te maken.",
          "Bak gedurende 75 tot 90 minuten of tot de bovenkant bruin is en het brood een beetje aanvoelt."
        ]
      },
      "fr": {
        "title": "Pain aux bananes et aux noix sans gluten Curious George's",
        "subtitle": "Le pain aux bananes et aux noix sans gluten de Curious George est p...",
        "description": "Le pain aux bananes et aux noix sans gluten de Curious George est peut-être exactement le petit-déjeuner que vous recherchez. Vous surveillez votre silhouette ? Cette recette en sert 8. 3 personnes étaient contentes d'avoir essayé cette recette. Un mélange de jus de citron, de beurre, de bananes très dorées et une poignée d'autres ingrédients suffisent pour rendre cette recette si délicieuse. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Préchauffer le four à 35",
          "Beurrer un moule à pain et réserver.",
          "Mélangez la farine, la levure chimique et le sel dans un bol et réservez.",
          "Crémer ensemble le shortening, le beurre et le sucre.",
          "Ajouter la banane, le citron et les œufs et battre pour incorporer.",
          "Ajouter lentement le mélange de farine et battre pour incorporer.",
          "Si vous utilisez des noix, jetez-les sans serrer sur une plaque à biscuits et faites-les griller pendant environ 4 minutes, en vérifiant toutes les minutes, jusqu'à ce qu'elles soient légèrement dorées.  Mélangez-les à la pâte et incorporez-les.",
          "Versez la pâte dans le moule préparé et appuyez avec une spatule pour aplatir.",
          "Cuire au four pendant 75 à 90 minutes ou jusqu'à ce que le dessus soit doré et que le pain cède un peu au toucher."
        ]
      }
    },
