    "servings": 6,
    "category": [
      "dessert"
    ],
    "image": "images/spoonacular-655279.jpg",
    "isGlutenFree": false,
    "isNutFree": false,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Peanut Butter Cookie Bars",
        "subtitle": "You can never have too many dessert recipes, so give Peanut Butter...",
        "description": "You can never have too many dessert recipes, so give Peanut Butter Cookie Bars a try. This recipe serves 6. From preparation to the plate, this recipe takes approximately 45 minutes. A mixture of baking soda, rolled oats, granulated sugar, and a handful of other ingredients are all it takes to make this recipe so tasty. This score is solid.",
        "instructions": [
          "Preheat oven to 375 degrees. In a small bowl with melted butter, beat in the brown sugar, granulated sugar, peanut butter and eggs. Set aside. In a separate bowl, combine the flour, bran, oats and baking soda. Stir mixture into butter mixture. In a glass baking dishes, press out half of dough mixture into each.",
          "Sprinkle peanut butter candy pieces across top of dough mixture. Cook until done, testing with toothpick, approximately 19 minutes. Cook the rest of the batter, if desired or refrigerate for another time.",
          "Remove to rack to cool.To serve, cut into bars."
        ]
      },
      "nl": {
        "title": "Koekjesrepen met pindakaas",
        "subtitle": "Je kunt nooit genoeg dessertrecepten hebben, dus probeer Peanut But...",
        "description": "Je kunt nooit genoeg dessertrecepten hebben, dus probeer Peanut Butter Cookie Bars eens. Dit recept is voor 6 personen. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Een mengsel van zuiveringszout, havermout, kristalsuiker en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Deze score is solide.",
        "instructions": [
          "Verwarm de oven voor op 375 graden. Klop in een kleine kom met gesmolten boter de bruine suiker, kristalsuiker, pindakaas en eieren erdoor. Zet opzij. Meng in een aparte kom de bloem, zemelen, haver en zuiveringszout. Roer het mengsel door het botermengsel. Druk in een glazen bakvorm de helft van het deegmengsel erin.",
          "Strooi stukjes pindakaassnoepje over het deegmengsel. Kook tot het klaar is, test met een tandenstoker, ongeveer 19 minuten. Kook de rest van het beslag, indien gewenst, of zet het nog een keer in de koelkast.",
          "Verwijder het in een rek om af te koelen. Snijd het in repen om te serveren."
        ]
      },
      "fr": {
        "title": "Barres aux biscuits au beurre de cacahuète",
        "subtitle": "Vous ne pouvez jamais avoir trop de recettes de desserts, alors ess...",
        "description": "Vous ne pouvez jamais avoir trop de recettes de desserts, alors essayez les barres de biscuits au beurre de cacahuète. Cette recette en sert 6. De la préparation à l'assiette, cette recette prend environ 45 minutes. Un mélange de bicarbonate de soude, de flocons d'avoine, de sucre cristallisé et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. 2 personnes ont réalisé cette recette et la referaient. Ce score est solide.",
        "instructions": [
          "Préchauffer le four à 375 degrés. Dans un petit bol avec le beurre fondu, incorporer la cassonade, le sucre cristallisé, le beurre de cacahuète et les œufs. Annuler. Dans un autre bol, mélanger la farine, le son, les flocons d'avoine et le bicarbonate de soude. Incorporer le mélange au mélange de beurre. Dans un plat allant au four, verser la moitié du mélange de pâte dans chacun.",
          "Saupoudrer les morceaux de bonbons au beurre de cacahuète sur le mélange de pâte. Cuire jusqu'à cuisson complète, en testant avec un cure-dent, environ 19 minutes. Cuire le reste de la pâte, si désiré ou réfrigérer une autre fois.",
          "Retirer sur une grille pour refroidir. Pour servir, couper en barres."
        ]
      }
    },
