    "translations": {
      "en": {
        "title": "Beet Greens and Poached Eggs",
        "subtitle": "The recipe Beet Greens and Poached Eggs can be made in around 45 mi...",
        "description": "The recipe Beet Greens and Poached Eggs can be made in around 45 minutes. 4 people were glad they tried this recipe. If you have juice of lemon, vinegar, leek, and a few other ingredients on hand, you can make it. It works well as a reasonably priced breakfast. It is a good option if you're following a gluten free and primal diet. This score is not so great. Users who liked this recipe also liked Sauteed Beet Greens with Poached Eggs, Creamy Polenta with Braised Greens and Poached Eggs, and Two-Potato Hash with Poached Eggs and Greens {.",
        "instructions": [
          "Heat a small skillet over medium low heat with 2 of water until small bubble start to rise.",
          "Add a pinch of salt and vinegar. Gently crack eggs into the water, slowly sliding them into the water. Cover and allow to simmer for 8 10 minutes until white is set and yolks are still runny. For this dish you want a runny yolk.",
          "Heat a large nonstick skillet over medium heat with coconut oil.",
          "Add leeks and sliced beets. Cook for 5 8 minutes until beets and leeks are tender.",
          "Add garlic and chopped baby beet greens. Cook for two minutes stirring often, then remove from heat and continue to stir until beet greens lightly wilt.",
          "Add a splash of lemon juice.",
          "Split greens among two plates and top each plate with a poached egg and a tablespoon of Parmesan cheese."
        ]
      },
      "nl": {
        "title": "Bietengranen en gepocheerde eieren",
        "subtitle": "Het recept Bietengranen en Gepocheerde Eieren maak je in ongeveer 4...",
        "description": "Het recept Bietengranen en Gepocheerde Eieren maak je in ongeveer 45 minuten. 4 mensen waren blij dat ze dit recept probeerden. Als je citroensap, azijn, prei en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het werkt goed als een redelijk geprijsd ontbijt. Het is een goede optie als je een glutenvrij en primair dieet volgt. Deze score is niet zo geweldig. Gebruikers die dit recept lekker vonden, hielden ook van gebakken bietengranen met gepocheerde eieren, romige polenta met gestoofde groenten en gepocheerde eieren, en twee-aardappelhasj met gepocheerde eieren en groenten {.",
        "instructions": [
          "Verhit een kleine koekenpan op middelhoog vuur met 2 eetlepels water tot er kleine belletjes beginnen te rijzen.",
          "Voeg een snufje zout en azijn toe. Breek de eieren voorzichtig in het water en laat ze langzaam in het water glijden. Dek af en laat 8-10 minuten sudderen tot het wit gestold is en de dooiers nog vloeibaar zijn. Voor dit gerecht heb je een vloeibaar eigeel nodig.",
          "Verhit een grote koekenpan met anti-aanbaklaag op middelhoog vuur met kokosolie.",
          "Voeg prei en gesneden bieten toe. Kook 5 8 minuten tot de bieten en prei gaar zijn.",
          "Voeg knoflook en gehakte babybieten toe. Kook gedurende twee minuten, vaak roerend, haal dan van het vuur en blijf roeren tot de bietengranen licht verwelken.",
          "Voeg een scheutje citroensap toe.",
          "Verdeel de groente over twee borden en beleg elk bord met een gepocheerd ei en een eetlepel Parmezaanse kaas."
        ]
      },
      "fr": {
        "title": "Feuilles de betterave et œufs pochés",
        "subtitle": "La recette Feuilles de betterave et œufs pochés peut être préparée...",
        "description": "La recette Feuilles de betterave et œufs pochés peut être préparée en 45 minutes environ. 4 personnes étaient contentes d'avoir essayé cette recette. Si vous avez du jus de citron, du vinaigre, du poireau et quelques autres ingrédients sous la main, vous pouvez le préparer. Cela fonctionne bien comme petit-déjeuner à un prix raisonnable. C'est une bonne option si vous suivez un régime sans gluten et primal. Ce score n'est pas si génial. Les utilisateurs qui ont aimé cette recette ont également aimé Feuilles de betterave sautées avec œufs pochés, Polenta crémeuse avec légumes braisés et œufs pochés et Hachis de deux pommes de terre avec œufs pochés et légumes verts {.",
        "instructions": [
          "Faites chauffer une petite poêle à feu moyen-doux avec 2 litres d'eau jusqu'à ce que de petites bulles commencent à monter.",
          "Ajoutez une pincée de sel et de vinaigre. Cassez délicatement les œufs dans l'eau, en les glissant lentement dans l'eau. Couvrir et laisser mijoter pendant 8 à 10 minutes jusqu'à ce que le blanc soit pris et que les jaunes soient encore coulants. Pour ce plat, vous voulez un jaune qui coule.",
          "Faites chauffer une grande poêle antiadhésive à feu moyen avec l'huile de coco.",
          "Ajouter les poireaux et les betteraves tranchées. Cuire 5 à 8 minutes jusqu'à ce que les betteraves et les poireaux soient tendres.",
          "Ajouter l'ail et les jeunes pousses de betterave hachées. Cuire pendant deux minutes en remuant souvent, puis retirer du feu et continuer à remuer jusqu'à ce que les feuilles de betterave se fanent légèrement.",
          "Ajoutez un peu de jus de citron.",
          "Répartissez les légumes verts dans deux assiettes et garnissez chaque assiette d'un œuf poché et d'une cuillère à soupe de parmesan."
        ]
      }
    },
