    "translations": {
      "en": {
        "title": "Rosemary Rum Raisin Soda Bread with Pecans",
        "subtitle": "Rosemary Rum Raisin Soda Bread with Pecans is a lacto ovo vegetaria...",
        "description": "Rosemary Rum Raisin Soda Bread with Pecans is a lacto ovo vegetarian recipe with 16 servings. Only a few people really liked this European dish. A mixture of anise seeds, rum, flour, and a handful of other ingredients are all it takes to make this recipe so flavorful. 4 people were impressed by this recipe. From preparation to the plate, this recipe takes about 45 minutes.",
        "instructions": [
          "Combine the rum and raisins in a small saucepan. Bring to a boil. Simmer for 30 seconds, then remove from heat. Cover and allow the raisins to macerate for at least 4 hours, but preferably overnight.",
          "When youre ready to bake the bread, preheat the oven to 375F.",
          "Coat a baking sheet with olive oil and lightly dust it with flour, or line it with parchment paper.",
          "In a large mixing bowl whisk together the flours, baking soda, salt, and rosemary. Stir in the toasted pecans.",
          "In a separate bowl combine the raisins with the rum, the yogurt, and honey.",
          "Add the wet ingredients to the dry.",
          "Mix until the dough is too stiff to stir. Use your hands to bring it together in the bowl.",
          "Add additional yogurt one teaspoon at a time if its too dry. You want a stiff, slightly tacky ball.",
          "Turn dough onto a lightly floured board and shape into a round loaf. (Dont over-knead the dough. Too much kneading will produce a tough bread.).",
          "Transfer the loaf to the prepared baking sheet. Use a sharp knife to make deep slashes across the top of the loaf, 4-6 cuts about half way through.",
          "Brush the top with milk.",
          "Sprinkle with seeds or oats if using.",
          "Bake for 40-45 minutes, until a toothpick comes out clean. When you tap the loaf, it will sound hollow.",
          "Cool on a wire rack.",
          "Serve warm or at room temperature with a generous slather of butter."
        ]
      },
      "nl": {
        "title": "Rozemarijn Rum Rozijnensodabrood met Pecannoten",
        "subtitle": "Rosemary Rum Rozijnensodabrood met Pecannoten is een lacto ovo-vege...",
        "description": "Rosemary Rum Rozijnensodabrood met Pecannoten is een lacto ovo-vegetarisch recept met 16 porties. Slechts een paar mensen vonden dit Europese gerecht erg lekker. Een mengsel van anijszaad, rum, bloem en een handvol andere ingrediënten is voldoende om dit recept zo smaakvol te maken. 4 mensen waren onder de indruk van dit recept. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Meng de rum en de rozijnen in een kleine pan. Breng aan de kook. Laat het 30 seconden sudderen en haal het dan van het vuur. Dek af en laat de rozijnen minimaal 4 uur, maar bij voorkeur een hele nacht, macereren.",
          "Als je klaar bent om het brood te bakken, verwarm de oven dan voor op 375F.",
          "Bestrijk een bakplaat met olijfolie en bestuif hem licht met bloem, of bekleed hem met bakpapier.",
          "Klop in een grote mengkom de bloem, het bakpoeder, het zout en de rozemarijn door elkaar. Roer de geroosterde pecannoten erdoor.",
          "Meng in een aparte kom de rozijnen met de rum, de yoghurt en de honing.",
          "Voeg de natte ingrediënten toe aan de droge.",
          "Meng tot het deeg te stijf is om te roeren. Gebruik je handen om het samen te brengen in de kom.",
          "Voeg extra yoghurt één theelepel per keer toe als het te droog is. Je wilt een stijve, enigszins plakkerige bal.",
          "Leg het deeg op een licht met bloem bestoven bord en vorm het tot een rond brood. (Kneed het deeg niet te veel. Te veel kneden levert een taai brood op.)",
          "Leg het brood op de voorbereide bakplaat. Maak met een scherp mes diepe inkepingen in de bovenkant van het brood, 4-6 inkepingen ongeveer halverwege.",
          "Bestrijk de bovenkant met melk.",
          "Bestrooi met zaden of haver als je het gebruikt.",
          "Bak gedurende 40-45 minuten, totdat een tandenstoker er schoon uitkomt. Als je op het brood tikt, klinkt het hol.",
          "Afkoelen op een rooster.",
          "Serveer warm of op kamertemperatuur met een flinke scheut boter."
        ]
      },
      "fr": {
        "title": "Pain soda au romarin, rhum et raisins secs avec pacanes",
        "subtitle": "Le pain soda au romarin, rhum et raisins secs avec pacanes est une...",
        "description": "Le pain soda au romarin, rhum et raisins secs avec pacanes est une recette lacto ovo végétarienne de 16 portions. Seules quelques personnes ont vraiment aimé ce plat européen. Un mélange de graines d'anis, de rhum, de farine et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. 4 personnes ont été impressionnées par cette recette. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Mélangez le rhum et les raisins secs dans une petite casserole. Porter à ébullition. Laisser mijoter 30 secondes, puis retirer du feu. Couvrir et laisser macérer les raisins secs pendant au moins 4 heures, mais de préférence toute la nuit.",
          "Lorsque vous êtes prêt à cuire le pain, préchauffez le four à 375F.",
          "Enduisez une plaque à pâtisserie d’huile d’olive et saupoudrez-la légèrement de farine ou tapissez-la de papier sulfurisé.",
          "Dans un grand bol, mélanger les farines, le bicarbonate de soude, le sel et le romarin. Incorporer les pacanes grillées.",
          "Dans un autre bol, mélangez les raisins secs avec le rhum, le yaourt et le miel.",
          "Ajouter les ingrédients humides aux ingrédients secs.",
          "Mélangez jusqu'à ce que la pâte soit trop ferme pour être agitée. Utilisez vos mains pour le rassembler dans le bol.",
          "Ajoutez du yaourt supplémentaire, une cuillère à café à la fois, s'il est trop sec. Vous voulez une balle rigide et légèrement collante.",
          "Retourner la pâte sur une planche légèrement farinée et façonner un pain rond. (Ne pétrissez pas trop la pâte. Trop de pétrissage produira un pain dur.).",
          "Transférer le pain sur la plaque à pâtisserie préparée. Utilisez un couteau bien aiguisé pour faire des entailles profondes sur le dessus du pain, 4 à 6 coupes environ à mi-chemin.",
          "Badigeonner le dessus de lait.",
          "Saupoudrer de graines ou d'avoine si vous en utilisez.",
          "Cuire au four pendant 40 à 45 minutes, jusqu'à ce qu'un cure-dent en ressorte propre. Lorsque vous tapez sur le pain, le son sera creux.",
          "Laisser refroidir sur une grille.",
          "Servir chaud ou à température ambiante avec une généreuse couche de beurre."
        ]
      }
    },
