    "image": "images/spoonacular-704655.jpg",
    "isGlutenFree": true,
    "isNutFree": false,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
