    "translations": {
      "en": {
        "title": "Delicious Limeade Triple Berry Smoothies",
        "subtitle": "Delicious Limeade Triple Berry Smoothies takes around 10 minutes fr...",
        "description": "Delicious Limeade Triple Berry Smoothies takes around 10 minutes from beginning to end. 2 people found this recipe to be yummy and satisfying. It works well as a rather cheap breakfast. It is brought to you by Pink When. If you have ground flax seed, limeade more, vanilla greek yogurt, and a few other ingredients on hand, you can make it. It is a good option if you're following a gluten free diet. If you like this recipe, you might also like recipes such as Delicious Limeade Triple Berry Smoothies, Delicious Limeade Triple Berry Smoothies, and Triple Berry Limeade Smoothies.",
        "instructions": [
          "Add all of the ingredients to the pitcher of your blender. Pulse 3-4 times to break up the ingredients and then turn the blender on full speed. Blend for about a minute or until completely smooth. This amount of time will depend on how powerful your blender is. It may take longer (or shorter!).",
          "Add more liquid as needed. This will also depend on how much water your fruit releases. If it’s too thick, add more almond milk or limeade until the smoothie reaches your desired consistency.",
          "Serve the smoothies immediately or pour into an airtight, freezer-safe container and freeze for up to 2 months. Defrost in the refrigerator for 24 hours before serving."
        ]
      },
      "nl": {
        "title": "Heerlijke Limeade Triple Berry Smoothies",
        "subtitle": "Heerlijke Limeade Triple Berry Smoothies duren van begin tot eind o...",
        "description": "Heerlijke Limeade Triple Berry Smoothies duren van begin tot eind ongeveer 10 minuten. 2 mensen vonden dit recept lekker en bevredigend. Het werkt goed als een vrij goedkoop ontbijt. Het wordt u aangeboden door Pink When. Als je gemalen lijnzaad, meer limoen, Griekse vanilleyoghurt en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het is een goede optie als je een glutenvrij dieet volgt. Als je dit recept lekker vindt, vind je misschien ook recepten leuk zoals Delicious Limeade Triple Berry Smoothies, Delicious Limeade Triple Berry Smoothies en Triple Berry Limeade Smoothies.",
        "instructions": [
          "Voeg alle ingrediënten toe aan de kan van uw blender. Pulseer 3-4 keer om de ingrediënten te breken en zet de blender vervolgens op volle snelheid. Meng ongeveer een minuut of tot het volledig glad is. Deze hoeveelheid tijd hangt af van hoe krachtig uw blender is. Het kan langer (of korter!) duren.",
          "Voeg indien nodig meer vloeistof toe. Dit zal ook afhangen van hoeveel water uw fruit vrijgeeft. Als het te dik is, voeg dan meer amandelmelk of limeade toe totdat de smoothie de gewenste consistentie heeft bereikt.",
          "Serveer de smoothies onmiddellijk of giet ze in een luchtdichte, diepvriesbestendige container en vries ze maximaal 2 maanden in. Ontdooi 24 uur in de koelkast voordat u het serveert."
        ]
      },
      "fr": {
        "title": "Délicieux smoothies aux trois baies et à la limeade",
        "subtitle": "Les délicieux smoothies aux trois baies et à la limeade prennent en...",
        "description": "Les délicieux smoothies aux trois baies et à la limeade prennent environ 10 minutes du début à la fin. 2 personnes ont trouvé cette recette délicieuse et satisfaisante. Cela fonctionne bien comme petit-déjeuner plutôt bon marché. Il vous est présenté par Pink When. Si vous avez des graines de lin moulues, du citron vert, du yaourt grec à la vanille et quelques autres ingrédients sous la main, vous pouvez le préparer. C'est une bonne option si vous suivez un régime sans gluten. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes telles que Délicieux smoothies aux trois baies et à la limeade, Délicieux smoothies aux trois baies et à la limeade et Smoothies aux trois baies et à la lime.",
        "instructions": [
          "Ajoutez tous les ingrédients dans le pichet de votre mixeur. Pulsez 3 à 4 fois pour briser les ingrédients, puis allumez le mélangeur à pleine vitesse. Mélanger pendant environ une minute ou jusqu'à ce que le mélange soit complètement lisse. Cette durée dépendra de la puissance de votre mixeur. Cela peut prendre plus de temps (ou moins !).",
          "Ajoutez plus de liquide si nécessaire. Cela dépendra également de la quantité d’eau libérée par vos fruits. S'il est trop épais, ajoutez plus de lait d'amande ou de limeade jusqu'à ce que le smoothie atteigne la consistance désirée.",
          "Servez les smoothies immédiatement ou versez-les dans un récipient hermétique allant au congélateur et congelez jusqu'à 2 mois. Décongeler au réfrigérateur pendant 24 heures avant de servir."
        ]
      }
    },
