        "description": "Als je ongeveer 45 minuten de tijd hebt om in de keuken te staan, zijn sperziebonen met pareluien en zalm wellicht een geweldig glutenvrij en pescatarisch recept om te proberen. 7 mensen vonden dit recept lekker en bevredigend. Slechts een paar mensen vonden dit hoofdgerecht erg lekker. Deze score is niet zo super. Als je dit recept lekker vindt, vind je misschien ook recepten leuk zoals Sperziebonen en Pareluitjes, Hartige Sperziebonen met champignons en Pareluitjes, en Hartige Sperziebonen met champignons en Pareluitjes.",
