          "Ajouter le bouillon de poulet et cuire encore une minute jusqu'à ce que le bouillon soit évaporé.",
          "Ajouter 1 cuillère à soupe de beurre et la cassonade ; baisser le feu à doux et mélanger doucement jusqu'à ce qu'il soit légèrement caramélisé.",
          "Retirer du feu et réserver au chaud.",
          "Remettez la poêle sur feu moyen-vif et faites fondre la cuillère à café de beurre restante au centre, ajoutez le saumon dessus et assaisonnez généreusement de Slavosalt. Cuire pendant 3 à 5 minutes jusqu'à ce qu'une croûte dorée se forme. Retourner et cuire encore 3 minutes.",
