        "title": "Vegan Chocolate Banana Pie",
        "subtitle": "Vegan Chocolate Banana Pie is a dessert that serves 6.",
        "description": "Vegan Chocolate Banana Pie is a dessert that serves 6. 23 people were impressed by this recipe. If you have pie crust, cornstarch-mixed, chocolate-melted in a bain marie, and a few other ingredients on hand, you can make it. From preparation to the plate, this recipe takes around 45 minutes. Users who liked this recipe also liked Vegan Banana Pie Cup, Vegan Banana Pie Cup, and White Chocolate Banana Cream Pie { Pie Party}.",
