    "translations": {
      "en": {
        "title": "Chicken Pasta With Anchovy Rosemary Sauce",
        "subtitle": "If you have around 45 minutes to spend in the kitchen, Chicken Past...",
        "description": "If you have around 45 minutes to spend in the kitchen, Chicken Pasta With Anchovy Rosemary Sauce might be an awesome dairy free recipe to try. This recipe serves 4. It works well as a rather inexpensive main course. 2 people were impressed by this recipe. A mixture of olive oil, garlic, juice of lemon, and a handful of other ingredients are all it takes to make this recipe so tasty.",
        "instructions": [
          "Place garlic, anchovies (with their oil), rosemary and lemon juice in a food processor.  Blend until fairly smooth.",
          "Add lemon juice followed by olive oil and continue to blend until smooth.  Cover and set aside.Season chicken with red pepper flakes, poultry seasoning and a pinch of kosher salt.  Set aside.Start a pot of water boiling for the pasta.",
          "Add a pinch of salt.  Once boiling, cook pasta to desired doneness, approximately 6-9 minutes for al dente.As pasta cooks, drizzle a bit of olive oil in a wide pan.  When hot, add the chicken and cook until no longer pink inside, approximately 5-7 minutes.",
          "Drain pasta and drop the noodles directly into the pan with the chicken.",
          "Add anchovy sauce and toss to coat.",
          "Sprinkle with fresh parsley if desired."
        ]
      },
      "nl": {
        "title": "Kippenpasta Met Ansjovis Rozemarijnsaus",
        "subtitle": "Als je ongeveer 45 minuten de tijd hebt om in de keuken te staan, i...",
        "description": "Als je ongeveer 45 minuten de tijd hebt om in de keuken te staan, is Kippasta met ansjovis-rozemarijnsaus wellicht een geweldig zuivelvrij recept om te proberen. Dit recept is voor 4 personen. Het werkt goed als een vrij goedkoop hoofdgerecht. 2 mensen waren onder de indruk van dit recept. Een mengsel van olijfolie, knoflook, citroensap en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken.",
        "instructions": [
          "Doe de knoflook, ansjovis (met hun olie), rozemarijn en citroensap in een keukenmachine.  Mix tot het redelijk glad is.",
          "Voeg citroensap toe, gevolgd door olijfolie en blijf mixen tot een gladde massa.  Dek af en zet opzij. Breng de kip op smaak met rode pepervlokken, gevogeltekruiden en een snufje koosjer zout.  Zet opzij. Zet een pan met water aan de kook voor de pasta.",
          "Voeg een snufje zout toe.  Zodra de pasta kookt, kookt u de pasta tot de gewenste gaarheid, ongeveer 6-9 minuten voor al dente. Terwijl de pasta kookt, sprenkel een beetje olijfolie in een grote pan.  Als het warm is, voeg je de kip toe en kook tot hij niet meer roze is van binnen, ongeveer 5-7 minuten.",
          "Giet de pasta af en doe de noedels direct in de pan met de kip.",
          "Ansjovissaus toevoegen en door elkaar roeren.",
          "Bestrooi eventueel met verse peterselie."
        ]
      },
      "fr": {
        "title": "Pâtes au poulet avec sauce aux anchois et au romarin",
        "subtitle": "Si vous avez environ 45 minutes à consacrer à la cuisine, les pâtes...",
        "description": "Si vous avez environ 45 minutes à consacrer à la cuisine, les pâtes au poulet avec sauce aux anchois et au romarin pourraient être une excellente recette sans produits laitiers à essayer. Cette recette en sert 4. Cela fonctionne bien comme plat principal plutôt bon marché. 2 personnes ont été impressionnées par cette recette. Un mélange d’huile d’olive, d’ail, de jus de citron et une poignée d’autres ingrédients suffisent pour rendre cette recette si savoureuse.",
        "instructions": [
          "Mettre l'ail, les anchois (avec leur huile), le romarin et le jus de citron dans un robot culinaire.  Mélanger jusqu'à ce qu'il soit assez lisse.",
          "Ajoutez le jus de citron suivi de l'huile d'olive et continuez à mélanger jusqu'à consistance lisse.  Couvrir et réserver. Assaisonner le poulet avec les flocons de piment rouge, l'assaisonnement pour volaille et une pincée de sel casher.  Réserver. Faites bouillir une casserole d'eau pour les pâtes.",
          "Ajoutez une pincée de sel.  Une fois à ébullition, faites cuire les pâtes jusqu'à la cuisson désirée, environ 6 à 9 minutes al dente. Pendant la cuisson des pâtes, versez un peu d'huile d'olive dans une grande poêle.  Lorsqu'il est chaud, ajoutez le poulet et faites cuire jusqu'à ce qu'il ne soit plus rose à l'intérieur, environ 5 à 7 minutes.",
          "Égouttez les pâtes et déposez les nouilles directement dans la poêle avec le poulet.",
          "Ajouter la sauce aux anchois et remuer pour bien enrober.",
          "Saupoudrer de persil frais si désiré."
        ]
      }
    },
