    "servings": 8,
    "category": [
      "snack",
      "main"
    ],
    "image": "images/spoonacular-638772.jpg",
    "isGlutenFree": true,
    "isNutFree": true,
    "isDairyFree": true,
    "isEggFree": true,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
