    "translations": {
      "en": {
        "title": "Chiquetaille: Cod Fish Salad",
        "subtitle": "Chiquetaille: Cod Fish Salad could be just the gluten free, dairy f...",
        "description": "Chiquetaille: Cod Fish Salad could be just the gluten free, dairy free, paleolithic, and primal recipe you've been looking for. This recipe serves 8. 3 people found this recipe to be yummy and satisfying. From preparation to the plate, this recipe takes roughly 45 minutes.",
        "instructions": [
          "Soak the cod in cold water in the refrigerator for 24 hours, changing the water 3 times.  In a large pot, bring to boil enough water to cover the fish and boil for about 20 minutes.",
          "Drain in a vegetable strainer and when cool, remove skin, bones and any unsightly fish parts.   Shred by hand.",
          "Mix the shredded fish with the vegetables, olive oil, cloves, salt, pepper and vinegar.   Refrigerate for at least 4 days.",
          "Serve spread on baguette slices for cocktails or as a salad with lettuce, tomatoes and hard boiled eggs."
        ]
      },
      "nl": {
        "title": "Chiquetaille: Kabeljauwvissalade",
        "subtitle": "Chiquetaille: Kabeljauwvissalade zou precies het glutenvrije, zuive...",
        "description": "Chiquetaille: Kabeljauwvissalade zou precies het glutenvrije, zuivelvrije, paleolithische en oorspronkelijke recept kunnen zijn waar u naar op zoek was. Dit recept serveert 8 personen. 3 mensen vonden dit recept lekker en bevredigend. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Week de kabeljauw in koud water in de koelkast gedurende 24 uur, waarbij u het water 3 keer ververst.  Breng in een grote pan voldoende water aan de kook om de vis onder water te zetten en kook ongeveer 20 minuten.",
          "Laat ze uitlekken in een groentezeef en verwijder, als ze afgekoeld zijn, het vel, de botten en eventuele lelijke delen van de vis.   Met de hand versnipperen.",
          "Meng de geraspte vis met de groenten, olijfolie, kruidnagel, zout, peper en azijn.   Zet minimaal 4 dagen in de koelkast.",
          "Serveer uitgesmeerd op stokbrood voor cocktails of als salade met sla, tomaten en hardgekookte eieren."
        ]
      },
      "fr": {
        "title": "Chiquetaille : Salade de Morue",
        "subtitle": "Chiquetaille : La salade de morue pourrait être la recette sans glu...",
        "description": "Chiquetaille : La salade de morue pourrait être la recette sans gluten, sans produits laitiers, paléolithique et primale que vous recherchiez. Cette recette en sert 8. 3 personnes ont trouvé cette recette délicieuse et satisfaisante. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Faire tremper le cabillaud dans l'eau froide au réfrigérateur pendant 24 heures en changeant l'eau 3 fois.  Dans une grande casserole, porter à ébullition suffisamment d'eau pour couvrir le poisson et laisser bouillir environ 20 minutes.",
          "Égoutter dans une passoire à légumes et une fois refroidi, retirer la peau, les arêtes et toutes les parties disgracieuses du poisson.   Déchiquetez à la main.",
          "Mélangez le poisson émincé avec les légumes, l'huile d'olive, les clous de girofle, le sel, le poivre et le vinaigre.   Réfrigérer au moins 4 jours.",
          "Servir à tartiner sur des tranches de baguette pour des cocktails ou en salade avec de la laitue, des tomates et des œufs durs."
        ]
      }
    },
