    "translations": {
      "en": {
        "title": "Shrimp and Avocado Salad",
        "subtitle": "Need a gluten free, dairy free, and pescatarian main course?",
        "description": "Need a gluten free, dairy free, and pescatarian main course? Shrimp and Avocado Salad could be an awesome recipe to try. From preparation to the plate, this recipe takes about 45 minutes. This recipe is liked by 8 foodies and cooks. This score is outstanding.",
        "instructions": [
          "Firstly, to cook the shrimp, heat the olive oil in a pan and once hot add the shrimp crushed garlic and chili flakes. It is important to get the oil nice and hot (not smoking, just before that point) your shrimp should sizzle when added to the pan. Check the back of the shrimp and when you see the colour change about half way up, turn them over. Do the same on the other side. This should only take a minute to two minutes maximum on both sides  otherwise you will get a rubbery result if you leave it too long. Squeeze over the lime juice  this too should bubble and reduce.",
          "Add a little salt and pepper, stir through, remove from the heat and set aside.",
          "Mix the dressing ingredients together, check for flavour, adjust if need be and set aside.",
          "Place all the salad ingredients in a bowl except the avocado and the salt and pepper. Prepare the avocado as you are about to serve otherwise it will turn brown. Once it is covered in the lime dressing, this will slow down the oxidization process and it wont go brown so easily.",
          "When you are ready to serve mix  of the avocado through the salad and add the dressing. Toss everything together. Taste to see if you need any salt and pepper.",
          "Place your shrimp on top of the salad with the rest of the avocado and sprinkle/pour any residue from the pan over your salad in which you cooked the shrimp. This is great flavour, so you dont want to lose it."
        ]
      },
      "nl": {
        "title": "Garnalen- en avocadosalade",
        "subtitle": "Een glutenvrij, zuivelvrij en pescatarisch hoofdgerecht nodig?",
        "description": "Een glutenvrij, zuivelvrij en pescatarisch hoofdgerecht nodig? Garnalen-avocadosalade kan een geweldig recept zijn om te proberen. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Dit recept is geliefd bij 8 foodies en koks. Deze score is uitmuntend.",
        "instructions": [
          "Om de garnalen te koken, verwarm je eerst de olijfolie in een pan en zodra deze heet is, voeg je de garnalen, geperste knoflook en chilivlokken toe. Het is belangrijk om de olie lekker heet te krijgen (niet roken, net voor dat punt). Uw garnalen moeten sissen als ze aan de pan worden toegevoegd. Controleer de achterkant van de garnalen en als je ongeveer halverwege de kleur ziet veranderen, draai ze dan om. Doe hetzelfde aan de andere kant. Dit duurt aan beide kanten slechts een minuut tot maximaal twee minuten, anders krijgt u een rubberachtig resultaat als u het te lang laat staan. Knijp het limoensap erover, ook dit moet borrelen en inkoken.",
          "Voeg een beetje zout en peper toe, roer door, haal van het vuur en zet opzij.",
          "Meng de ingrediënten voor de dressing door elkaar, controleer op smaak, pas eventueel aan en zet opzij.",
          "Doe alle ingrediënten voor de salade in een kom, behalve de avocado en het zout en de peper. Bereid de avocado voor op het moment dat je hem gaat serveren, anders wordt hij bruin. Als het eenmaal bedekt is met de limoendressing, zal dit het oxidatieproces vertragen en zal het niet zo gemakkelijk bruin worden.",
          "Wanneer je klaar bent om te serveren, meng je de avocado door de salade en voeg je de dressing toe. Gooi alles samen. Proef of je nog zout en peper nodig hebt.",
          "Leg je garnalen op de salade met de rest van de avocado en strooi/giet eventuele resten uit de pan over je salade waarin je de garnalen hebt gekookt. Dit is een geweldige smaak, dus je wilt deze niet verliezen."
        ]
      },
      "fr": {
        "title": "Salade de crevettes et avocat",
        "subtitle": "Besoin d'un plat principal sans gluten, sans produits laitiers et p...",
        "description": "Besoin d'un plat principal sans gluten, sans produits laitiers et pescatarien ? La salade de crevettes et d'avocat pourrait être une recette géniale à essayer. De la préparation à l'assiette, cette recette prend environ 45 minutes. Cette recette est appréciée par 8 gourmets et cuisiniers. Ce score est exceptionnel.",
        "instructions": [
          "Tout d'abord, pour cuire les crevettes, faites chauffer l'huile d'olive dans une poêle et une fois chaude, ajoutez les crevettes, l'ail écrasé et les flocons de piment. Il est important que l'huile soit bien chaude (ne fume pas, juste avant ce point), vos crevettes doivent grésiller lorsqu'elles sont ajoutées à la poêle. Vérifiez le dos des crevettes et lorsque vous voyez la couleur changer à mi-hauteur, retournez-les. Faites la même chose de l'autre côté. Cela ne devrait prendre qu’une minute à deux minutes maximum des deux côtés sinon vous obtiendrez un résultat caoutchouteux si vous le laissez trop longtemps. Pressez le jus de citron vert, celui-ci devrait également bouillonner et réduire.",
          "Ajoutez un peu de sel et de poivre, mélangez, retirez du feu et réservez.",
          "Mélangez les ingrédients de la vinaigrette, vérifiez la saveur, rectifiez si besoin et réservez.",
          "Mettez tous les ingrédients de la salade dans un bol sauf l'avocat et le sel et le poivre. Préparez l’avocat au moment de le servir sinon il brunira. Une fois recouvert de vinaigrette à la chaux, cela ralentira le processus d’oxydation et il ne brunira pas si facilement.",
          "Lorsque vous êtes prêt à servir, mélangez l'avocat dans la salade et ajoutez la vinaigrette. Mélangez le tout ensemble. Goûtez pour voir si vous avez besoin de sel et de poivre.",
          "Placez vos crevettes sur la salade avec le reste de l'avocat et saupoudrez/versez les éventuels résidus de la poêle sur votre salade dans laquelle vous avez cuit les crevettes. C'est une saveur délicieuse, vous ne voulez donc pas la perdre."
        ]
      }
    },
