    "image": "images/spoonacular-640323.jpg",
    "isGlutenFree": false,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": false,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": true,
    "translations": {
      "en": {
        "title": "Crab Wontons",
        "subtitle": "Crab Wontons might be just the Chinese recipe you are searching for.",
        "description": "Crab Wontons might be just the Chinese recipe you are searching for. From preparation to the plate, this recipe takes around 45 minutes. 13 people were glad they tried this recipe. It is a good option if you're following a pescatarian diet. If you have ground pepper, cream cheese, garlic, and a few other ingredients on hand, you can make it. It works well as a hor d'oeuvre.",
        "instructions": [
          "Preheat oven to 350F. Spray a mini muffin tin with nonstick cooking spray.",
          "In a medium bowl, combine crab meat, cream cheese, mayonaise, soy sauce, garlic, onion powder,and pepper.",
          "Mix until well combined.",
          "Place 1 won ton wrapper in each 12 mini muffin cups. The edges of the won ton wrappers will extend beyond the mini muffin tin cups and may need to be folded slightly. Fill the center of each won ton cup with crab mixture.",
          "Bake 15 to 20 minutes or until edges of cups are golden brown and filling is heated through."
        ]
      },
      "nl": {
        "title": "Krab Wontons",
        "subtitle": "Krabwontons is misschien wel het Chinese recept waar u naar op zoek...",
        "description": "Krabwontons is misschien wel het Chinese recept waar u naar op zoek bent. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. 13 mensen waren blij dat ze dit recept probeerden. Het is een goede optie als je een pescatarisch dieet volgt. Als je gemalen peper, roomkaas, knoflook en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het werkt goed als hor d'oeuvre.",
        "instructions": [
          "Verwarm de oven voor op 350F. Spuit een mini-muffinvormpje in met anti-aanbakspray.",
          "Meng in een middelgrote kom krabvlees, roomkaas, mayonaise, sojasaus, knoflook, uienpoeder en peper.",
          "Meng tot alles goed gemengd is.",
          "Plaats 1 gewonnen ton-verpakking in elke 12 mini-muffinbekers. De randen van de won ton-wikkels steken uit tot voorbij de mini-muffinvormpjes en moeten mogelijk lichtjes worden gevouwen. Vul het midden van elke won ton-beker met krabmengsel.",
          "Bak 15 tot 20 minuten of tot de randen van de kopjes goudbruin zijn en de vulling is opgewarmd."
        ]
      },
      "fr": {
        "title": "Wontons au crabe",
        "subtitle": "Les Wontons au crabe pourraient bien être la recette chinoise que v...",
        "description": "Les Wontons au crabe pourraient bien être la recette chinoise que vous recherchez. De la préparation à l'assiette, cette recette prend environ 45 minutes. 13 personnes étaient heureuses d'avoir essayé cette recette. C'est une bonne option si vous suivez un régime pescatarien. Si vous avez du poivre moulu, du fromage à la crème, de l’ail et quelques autres ingrédients sous la main, vous pouvez le préparer. Cela fonctionne bien comme un hor d'œuvre.",
        "instructions": [
          "Préchauffer le four à 350F. Vaporiser un moule à mini muffins avec un enduit à cuisson antiadhésif.",
          "Dans un bol moyen, mélanger la chair de crabe, le fromage à la crème, la mayonnaise, la sauce soja, l'ail, la poudre d'oignon et le poivre.",
          "Mélanger jusqu'à ce que le tout soit bien mélangé.",
          "Placer 1 emballage de won ton dans chacun des 12 mini moules à muffins. Les bords des emballages de won ton s'étendront au-delà des moules à mini muffins et devront peut-être être légèrement pliés. Remplissez le centre de chaque tasse de won ton avec le mélange de crabe.",
          "Cuire au four de 15 à 20 minutes ou jusqu'à ce que les bords des moules soient dorés et que la garniture soit bien chaude."
        ]
      }
    },
