    "translations": {
      "en": {
        "title": "DAIRY-FREE COCOA CUPCAKES WITH PEANUT BUTTER FILLING, MARSHMALLOW FROSTING",
        "subtitle": "DAIRY-FREE COCOA CUPCAKES WITH PEANUT BUTTER FILLING, MARSHMALLOW F...",
        "description": "DAIRY-FREE COCOA CUPCAKES WITH PEANUT BUTTER FILLING, MARSHMALLOW FROSTING might be a good recipe to expand your dessert collection. It is an inexpensive recipe for fans of American food. Head to the store and pick up baking powder, soy milk, jif natural creamy peanut butter, and a few other things to make it today. From preparation to the plate, this recipe takes approximately 45 minutes. This score is rather bad.",
        "instructions": [
          "Heat oven to 350F.  Line a 12-cup muffin tin with paper liners.  In large bowl, whisk together cocoa powder, flour, baking powder, baking soda and salt.  In medium bowl  whisk egg, oil, sugars, flavorings and coffee.  Stir wet ingredients into dry ingredients using a spoon or spatula.  Batter will be somewhat lumpy -- do not over mix it to make it smooth.  Using an ice cream scoop (1/4 cup), fill paper liners.",
          "Place chocolate into one bottom corner of a resealable plastic bag.  Microwave on high about 30 seconds.  Continue microwaving on high at 10-second intervals until chocolate is melted.  Very carefully cut the tiniest corner to make a very small hole through which the chocolate may be drizzled onto the frosting.  Lightly sprinkle peanuts over cupcakes.TIME-SAVING TIPS:  Instead of making peanut butter filling, just use Peanut Butter & Co.'s White Chocolate Wonderful Peanut Butter.  If you're not lactose intolerant, you could use a cake mix for the cupcakes, but you will have to double the other ingredients."
        ]
      },
      "nl": {
        "title": "ZUIVELVRIJE CACAOCUPCAKES MET PINDAKAASVULLING, MARSHMALLOW glazuur",
        "subtitle": "ZUIVELVRIJE CACAOCUPCAKES MET PINDAKAASVULLING, MARSHMALLOW FROSTIN...",
        "description": "ZUIVELVRIJE CACAOCUPCAKES MET PINDAKAASVULLING, MARSHMALLOW FROSTING zijn misschien een goed recept om je dessertcollectie uit te breiden. Het is een goedkoop recept voor fans van Amerikaans eten. Ga naar de winkel en koop bakpoeder, sojamelk, jif natuurlijke romige pindakaas en nog een paar andere dingen om het vandaag te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Deze score is nogal slecht.",
        "instructions": [
          "Verwarm de oven tot 350F.  Bekleed een muffinvorm met 12 kopjes met papieren vormpjes.  Meng in een grote kom cacaopoeder, bloem, bakpoeder, zuiveringszout en zout.  Klop in een middelgrote kom het ei, de olie, de suikers, de smaakstoffen en de koffie.  Roer natte ingrediënten door droge ingrediënten met een lepel of spatel.  Het beslag zal enigszins klonterig zijn; meng het niet te lang om het glad te maken.  Gebruik een ijsschep (1/4 kopje) om de papieren voeringen te vullen.",
          "Plaats chocolade in een onderste hoek van een hersluitbare plastic zak.  Magnetron op de hoogste stand, ongeveer 30 seconden.  Ga door met de magnetron op de hoogste stand met tussenpozen van 10 seconden totdat de chocolade is gesmolten.  Snijd heel voorzichtig het kleinste hoekje af, zodat er een heel klein gaatje ontstaat waardoor de chocolade op het glazuur kan worden gedruppeld.  Strooi de pinda's lichtjes over de cupcakes. TIJDBESPARENDE TIPS: Gebruik in plaats van pindakaasvulling gewoon Peanut Butter & Co.'s White Chocolate Wonderful Peanut Butter.  Als je geen lactose-intolerantie hebt, kun je voor de cupcakes een cakemix gebruiken, maar dan moet je de overige ingrediënten verdubbelen."
        ]
      },
      "fr": {
        "title": "CUPCAKES AU CACAO SANS PRODUITS LAITIERS FOURRÉS AU BEURRE D'ARACHIDES, GLAÇAGE À LA GUIMAUVE",
        "subtitle": "CUPCAKES AU CACAO SANS PRODUITS LAITIERS FOURRÉS AU BEURRE D'ARACHI...",
        "description": "CUPCAKES AU CACAO SANS PRODUITS LAITIERS FOURRÉS AU BEURRE D'ARACHIDES, GLAÇAGE À LA GUIMAUVE pourraient être une bonne recette pour élargir votre collection de desserts. 8 personnes ont réalisé cette recette et la referaient. C'est une recette peu coûteuse pour les amateurs de cuisine américaine. Rendez-vous au magasin et procurez-vous de la levure chimique, du lait de soja, du beurre de cacahuète crémeux naturel et quelques autres choses pour le préparer aujourd'hui. De la préparation à l'assiette, cette recette prend environ 45 minutes. Ce score est plutôt mauvais.",
        "instructions": [
          "Chauffer le four à 350F.  Tapisser un moule à muffins de 12 tasses de caissettes en papier.  Dans un grand bol, fouetter ensemble la poudre de cacao, la farine, la levure chimique, le bicarbonate de soude et le sel.  Dans un bol moyen, fouetter l'œuf, l'huile, les sucres, les arômes et le café.  Incorporer les ingrédients humides aux ingrédients secs à l'aide d'une cuillère ou d'une spatule.  La pâte sera un peu grumeleuse – ne la mélangez pas trop pour la rendre lisse.  À l'aide d'une cuillère à crème glacée (1/4 tasse), remplissez des caissettes en papier.",
          "Placez le chocolat dans un coin inférieur d'un sac en plastique refermable.  Cuire au micro-ondes à puissance maximale environ 30 secondes.  Continuez à passer au micro-ondes à puissance élevée à intervalles de 10 secondes jusqu'à ce que le chocolat soit fondu.  Coupez très soigneusement le plus petit coin pour faire un tout petit trou à travers lequel le chocolat pourra être versé sur le glaçage.  Saupoudrez légèrement les cacahuètes sur les cupcakes. CONSEILS POUR GAGNER DU TEMPS : Au lieu de faire une garniture au beurre de cacahuète, utilisez simplement le merveilleux beurre de cacahuète au chocolat blanc de Peanut Butter & Co..  Si vous n'êtes pas intolérant au lactose, vous pouvez utiliser une préparation à gâteau pour les cupcakes, mais vous devrez doubler les autres ingrédients."
        ]
      }
    },
