    "translations": {
      "en": {
        "title": "Baked Ratatouille",
        "subtitle": "Baked Ratatouille takes approximately 45 minutes from beginning to...",
        "description": "Baked Ratatouille takes approximately 45 minutes from beginning to end. It works well as a main course. This recipe is typical of Mediterranean cuisine. If you have eggplant, bell peppers, olive oil, and a few other ingredients on hand, you can make it. It is a good option if you're following a gluten free, lacto ovo vegetarian, and primal diet. 2 people were glad they tried this recipe. This score is tremendous.",
        "instructions": [
          "Heat oil in a heavy, large Dutch oven over medium heat.",
          "Add garlic; stir 1 minute.",
          "Add eggplant, green bell peppers, tomatoes, onion, zucchini and basil.",
          "Saute for 5 minutes. Cover and simmer until all vegetables are tender, stirring occasionally, about 25 minutes.Uncover pot and simmer until juice thickens, stirring occasionally, about 10 minutes.",
          "Mix in vinegar; season to taste with salt and pepper.Preheat oven to 350 degrees.",
          "Spread in 9-inch pie dish.",
          "Sprinkle with cheese, if desired.",
          "Bake until heated through, about 20 minutes.This recipe yields about 3 cups."
        ]
      },
      "nl": {
        "title": "Gebakken Ratatouille",
        "subtitle": "Gebakken Ratatouille duurt ongeveer 45 minuten van begin tot eind.",
        "description": "Gebakken Ratatouille duurt ongeveer 45 minuten van begin tot eind. Het werkt goed als hoofdgerecht. Dit recept is typisch voor de mediterrane keuken. Als je aubergine, paprika, olijfolie en een paar andere ingrediënten bij de hand hebt, kun je het maken. Het is een goede optie als je een glutenvrij, lacto-ovo-vegetarisch en oerdieet volgt. 2 mensen waren blij dat ze dit recept probeerden. Deze score is enorm.",
        "instructions": [
          "Verhit olie in een zware, grote Nederlandse oven op middelhoog vuur.",
          "Voeg knoflook toe; roer 1 minuut.",
          "Voeg aubergine, groene paprika, tomaten, ui, courgette en basilicum toe.",
          "Bak gedurende 5 minuten. Dek af en laat sudderen tot alle groenten gaar zijn, af en toe roeren, ongeveer 25 minuten. Haal het deksel van de pan en laat sudderen tot het sap dikker wordt, af en toe roeren, ongeveer 10 minuten.",
          "Meng azijn; breng op smaak met zout en peper. Verwarm de oven voor op 350 graden.",
          "Verspreid in een taartvorm van 9 inch.",
          "Bestrooi eventueel met kaas.",
          "Bak tot het gaar is, ongeveer 20 minuten. Dit recept levert ongeveer 3 kopjes op."
        ]
      },
      "fr": {
        "title": "Ratatouille au four",
        "subtitle": "La Ratatouille au four prend environ 45 minutes du début à la fin.",
        "description": "La Ratatouille au four prend environ 45 minutes du début à la fin. Cela fonctionne bien comme plat principal. Cette recette est typique de la cuisine méditerranéenne. Si vous avez des aubergines, des poivrons, de l’huile d’olive et quelques autres ingrédients sous la main, vous pouvez le préparer. C'est une bonne option si vous suivez un régime sans gluten, lacto ovo végétarien et primal. 2 personnes étaient contentes d'avoir essayé cette recette. Ce score est formidable.",
        "instructions": [
          "Chauffer l’huile dans une grande cocotte à feu moyen.",
          "Ajouter l'ail; remuer 1 minute.",
          "Ajouter les aubergines, les poivrons verts, les tomates, l'oignon, la courgette et le basilic.",
          "Faire sauter pendant 5 minutes. Couvrir et laisser mijoter jusqu'à ce que tous les légumes soient tendres, en remuant de temps en temps, environ 25 minutes. Découvrir la casserole et laisser mijoter jusqu'à ce que le jus épaississe, en remuant de temps en temps, environ 10 minutes.",
          "Incorporer le vinaigre; assaisonner au goût avec du sel et du poivre. Préchauffer le four à 350 degrés.",
          "Étaler dans un plat à tarte de 9 pouces.",
          "Saupoudrer de fromage, si désiré.",
          "Cuire au four jusqu'à ce que le tout soit bien chaud, environ 20 minutes. Cette recette donne environ 3 tasses."
        ]
      }
    },
