        "description": "Si vous souhaitez ajouter d’autres recettes sans gluten à votre boîte de recettes, la tarte au bœuf et au cottage pourrait être une recette que vous devriez essayer. Cette recette pour 8 personnes. Un mélange de légumes, d'ail, de parmesan et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. 6 personnes ont trouvé cette recette délicieuse et satisfaisante. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
