    "translations": {
      "en": {
        "title": "Classic French Mussels",
        "subtitle": "You can never have too many hor d'oeuvre recipes, so give Classic F...",
        "description": "You can never have too many hor d'oeuvre recipes, so give Classic French Mussels a try. Watching your figure? From preparation to the plate, this recipe takes about 45 minutes. It is a reasonably priced recipe for fans of Mediterranean food. If you have buttermilk, parsley, butter, and a few other ingredients on hand, you can make it. This score is solid.",
        "instructions": [
          "Scrub mussels with a stiff brush, discard any that are open and stay that way even when you close the shell. Discard any with broken shells.Soak them in cool clean water for at least an hour. Mussels are alive and breathing and have taken in sand over time. This allows them to expel the sand.Mussels have a small fibrous \"beard\" that should be removed. Pull it out toward the hinge of the shell to keep from injuring the mussel.",
          "Heat the olive oil in a large pot over medium-high heat.",
          "Add the shallots and garlic and cook until soft, about 5 minutes.",
          "Add the mussels, wine, buttermilk, butter, and parsley and season well with the kosher salt. Give it a good stir, cover the pot, and cook until mussels open and are cooked through, 10 to 15 minutes. Divide the mussels and the juices between 2 bowls and serve with a crusty whole-grain bread to sop up that wonderful sauce."
        ]
      },
      "nl": {
        "title": "Klassieke Franse Mosselen",
        "subtitle": "Je kunt nooit genoeg hor d'oeuvre-recepten hebben, dus probeer Klas...",
        "description": "Je kunt nooit genoeg hor d'oeuvre-recepten hebben, dus probeer Klassieke Franse Mosselen eens. Op je figuur letten? Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Het is een redelijk geprijsd recept voor liefhebbers van mediterrane gerechten. Als je karnemelk, peterselie, boter en een paar andere ingrediënten bij de hand hebt, kun je het maken. Deze score is solide.",
        "instructions": [
          "Boen de mosselen met een harde borstel, gooi de openstaande mosselen weg en blijf zo, zelfs als je de schelp sluit. Gooi ze met gebroken schelpen weg. Week ze minimaal een uur in koud, schoon water. Mosselen leven en ademen en hebben in de loop van de tijd zand opgenomen. Hierdoor kunnen ze het zand verdrijven. Mosselen hebben een kleine vezelige \"baard\" die verwijderd moet worden. Trek hem naar buiten richting het scharnier van de schelp om te voorkomen dat de mossel gewond raakt.",
          "Verhit de olijfolie in een grote pan op middelhoog vuur.",
          "Voeg de sjalotten en knoflook toe en kook tot ze zacht zijn, ongeveer 5 minuten.",
          "Voeg de mosselen, wijn, karnemelk, boter en peterselie toe en breng goed op smaak met het koosjere zout. Roer het goed door, dek de pan af en kook tot de mosselen opengaan en gaar zijn, 10 tot 15 minuten. Verdeel de mosselen en het sap over 2 kommen en serveer met een knapperig volkorenbrood om de heerlijke saus op te zuigen."
        ]
      },
      "fr": {
        "title": "Moules françaises classiques",
        "subtitle": "Vous n'aurez jamais trop de recettes de hors-d'œuvre, alors essayez...",
        "description": "Vous n'aurez jamais trop de recettes de hors-d'œuvre, alors essayez les moules françaises classiques. Vous surveillez votre silhouette ? De la préparation à l'assiette, cette recette prend environ 45 minutes. 2 personnes ont réalisé cette recette et la referaient. C'est une recette à prix raisonnable pour les amateurs de cuisine méditerranéenne. Si vous avez du babeurre, du persil, du beurre et quelques autres ingrédients sous la main, vous pouvez le préparer. Ce score est solide.",
        "instructions": [
          "Frottez les moules avec une brosse dure, jetez celles qui sont ouvertes et restez ainsi même lorsque vous fermez la coquille. Jetez ceux dont la coquille est cassée. Faites-les tremper dans de l’eau fraîche et propre pendant au moins une heure. Les moules sont vivantes, respirent et ont absorbé du sable au fil du temps. Cela leur permet d'expulser le sable. Les moules ont une petite « barbe » fibreuse qu'il convient d'enlever. Tirez-le vers la charnière de la coquille pour éviter de blesser la moule.",
          "Faites chauffer l'huile d'olive dans une grande casserole à feu moyen-vif.",
          "Ajouter les échalotes et l'ail et cuire jusqu'à ce qu'ils soient tendres, environ 5 minutes.",
          "Ajouter les moules, le vin, le babeurre, le beurre et le persil et bien assaisonner avec le sel casher. Remuez bien, couvrez la casserole et faites cuire jusqu'à ce que les moules s'ouvrent et soient bien cuites, 10 à 15 minutes. Répartissez les moules et leur jus dans 2 bols et servez avec un pain complet croustillant pour absorber cette merveilleuse sauce."
        ]
      }
    },
