    "translations": {
      "en": {
        "title": "Green Bean Poriyal",
        "subtitle": "Green Bean Poriyal might be a good recipe to expand your side dish...",
        "description": "Green Bean Poriyal might be a good recipe to expand your side dish collection. Watching your figure? This recipe serves 6. This recipe is liked by 24 foodies and cooks. This recipe from foodandspice.blogspot.com requires asafetida, brown mustard seeds, chana dal, and cumin seeds. From preparation to the plate, this recipe takes around 45 minutes. Users who liked this recipe also liked beetroot carrot poriyal , how to make beetroot carrot poriyal, french beans poriyal , how to make french beans poriyal, and beetroot carrot poriyal , how to make beetroot carrot poriyal.",
        "instructions": [
          "Soak the tamarind pulp in 2/3 cup boiling water for 40 minutes. Strain the tamarind into a small bowl, pressing down on the pulp to squeeze as much liquid as you can. Set the drained tamarind liquid aside.In a large frying pan or wok, heat the oil over medium heat until hot.",
          "Add the mustard seeds and cumin seeds to the pan and cook for a few minutes. Now add the urad and toor or chana dals, chilli, asafetida and curry leaves. Fry for another few minutes until the mustard seeds turn grey and begin to splutter and pop.Now add the green beans, about 3 tablespoons of the tamarind water, and salt. Reduce the heat to medium-low and cover. Cook until the beans are tender, about 5 to 7 minutes. Stir in the coconut and cook for another few minutes.",
          "Remove from heat and taste for seasoning.",
          "Serve warm alongside some fresh cooked white rice and your favorite dal dishes."
        ]
      },
      "nl": {
        "title": "Groene Bonen Poriyal",
        "subtitle": "Green Bean Poriyal is misschien een goed recept om je bijgerechtcol...",
        "description": "Green Bean Poriyal is misschien een goed recept om je bijgerechtcollectie uit te breiden. Op je figuur letten? Dit recept is voor 6 personen. Dit recept is geliefd bij 24 foodies en koks. Voor dit recept van foodandspice.blogspot.com heb je asafetida, bruin mosterdzaad, chana dal en komijnzaad nodig. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Gebruikers die dit recept leuk vonden, hielden ook van rode biet poriyal, hoe je rode biet poriyal maakt, sperziebonen poriyal, hoe je sperziebonen poriyal maakt, en rode biet poriyal, hoe je rode biet poriyal maakt.",
        "instructions": [
          "Week de tamarindepulp in 2/3 kopje kokend water gedurende 40 minuten. Zeef de tamarinde in een kleine kom en druk op het vruchtvlees om zoveel mogelijk vloeistof uit te persen. Zet het uitgelekte tamarindevocht opzij. Verhit de olie in een grote koekenpan of wok op middelhoog vuur tot deze heet is.",
          "Voeg het mosterdzaad en komijnzaad toe aan de pan en kook een paar minuten. Voeg nu de urad en toor of chana dals, chili, asafetida en curryblaadjes toe. Bak nog een paar minuten tot de mosterdzaadjes grijs worden en beginnen te sputteren en ploffen. Voeg nu de sperziebonen, ongeveer 3 eetlepels tamarindewater en zout toe. Zet het vuur middelhoog en dek af. Kook tot de bonen gaar zijn, ongeveer 5 tot 7 minuten. Roer de kokosnoot erdoor en kook nog een paar minuten.",
          "Haal van het vuur en proef naar kruiden.",
          "Serveer warm naast wat vers gekookte witte rijst en je favoriete dalgerechten."
        ]
      },
      "fr": {
        "title": "Poriyal aux haricots verts",
        "subtitle": "Le Poriyal aux haricots verts pourrait être une bonne recette pour...",
        "description": "Le Poriyal aux haricots verts pourrait être une bonne recette pour élargir votre collection de plats d'accompagnement. Vous surveillez votre silhouette ? Cette recette est pour 6 personnes. Cette recette est appréciée par 24 gourmets et cuisiniers. Cette recette de foodandspice.blogspot.com nécessite de l'asafetida, des graines de moutarde brune, du chana dal et des graines de cumin. De la préparation à l'assiette, cette recette prend environ 45 minutes. Les utilisateurs qui ont aimé cette recette ont également aimé le poriyal de betterave et de carotte, comment faire du poriyal de betterave et de carotte, le poriyal de haricots verts, comment faire le poriyal de haricots verts, et le poriyal de carotte et de betterave, comment faire le poriyal de carotte et de betterave.",
        "instructions": [
          "Faire tremper la pulpe de tamarin dans 2/3 tasse d'eau bouillante pendant 40 minutes. Filtrez le tamarin dans un petit bol, en appuyant sur la pulpe pour presser autant de liquide que possible. Réserver le liquide de tamarin égoutté. Dans une grande poêle ou un wok, faire chauffer l'huile à feu moyen jusqu'à ce qu'elle soit chaude.",
          "Ajoutez les graines de moutarde et les graines de cumin dans la poêle et laissez cuire quelques minutes. Ajoutez maintenant l'urad et le toor ou le chana dals, le piment, l'asafetida et les feuilles de curry. Faites frire encore quelques minutes jusqu'à ce que les graines de moutarde deviennent grises et commencent à crépiter et à éclater. Ajoutez maintenant les haricots verts, environ 3 cuillères à soupe d'eau de tamarin et du sel. Réduire le feu à moyen-doux et couvrir. Cuire jusqu'à ce que les haricots soient tendres, environ 5 à 7 minutes. Incorporer la noix de coco et cuire encore quelques minutes.",
          "Retirer du feu et goûter pour l'assaisonnement.",
          "Servir chaud avec du riz blanc fraîchement cuit et vos plats de dal préférés."
        ]
      }
    },
