    "translations": {
      "en": {
        "title": "The Secret to Easy Skillet Filet Mignon Steak Tacos",
        "subtitle": "The recipe The Secret to Easy Skillet Filet Mignon Steak Tacos coul...",
        "description": "The recipe The Secret to Easy Skillet Filet Mignon Steak Tacos could satisfy your Mexican craving in roughly 20 minutes. It works well as a pretty expensive main course for valentin day. 3 people were glad they tried this recipe. Head to the store and pick up sou cream, olive oil extra virgin, filet mignon steaks, and a few other things to make it today. It is a good option if you're following a gluten free and ketogenic diet. It is brought to you by Pink When. This score is solid.",
        "instructions": [
          "Heat the skillet on medium to low heat.Rub the steaks with olive oil and season with cracked black pepper. Slowly cook the filets until they have reached your desired specifications. We like to cook ours to be medium done, and that averages about 7 minutes on each side.",
          "Remove the filets from the heat and slice thinly and lengthwise. Use a clean skillet over medium heat and warm up the corn tortillas. Top the tortillas with steak, guacamole, sour cream, and shredded cheese."
        ]
      },
      "nl": {
        "title": "Het geheim van Easy Skillet Filet Mignon Steak Tacos",
        "subtitle": "Het recept Het geheim van Easy Skillet Filet Mignon Steak Tacos kan...",
        "description": "Het recept Het geheim van Easy Skillet Filet Mignon Steak Tacos kan uw Mexicaanse trek in ongeveer 20 minuten stillen. Het werkt goed als een behoorlijk duur hoofdgerecht voor Valentijnsdag. 3 mensen waren blij dat ze dit recept probeerden. Ga naar de winkel en koop souroom, extra vierge olijfolie, filet mignon-steaks en nog een paar andere dingen om het vandaag te maken. Het is een goede optie als je een glutenvrij en ketogeen dieet volgt. Het wordt u aangeboden door Pink When. Deze score is solide.",
        "instructions": [
          "Verhit de koekenpan op middelhoog tot laag vuur. Wrijf de steaks in met olijfolie en breng op smaak met gemalen zwarte peper. Kook de filets langzaam totdat ze de gewenste specificaties hebben bereikt. Wij koken de onze graag medium gaar, en dat duurt gemiddeld ongeveer 7 minuten aan elke kant.",
          "Haal de filets van het vuur en snij ze in dunne plakjes in de lengte. Gebruik een schone koekenpan op middelhoog vuur en verwarm de maïstortilla's. Beleg de tortilla's met biefstuk, guacamole, zure room en geraspte kaas."
        ]
      },
      "fr": {
        "title": "Le secret des tacos faciles au steak et au filet mignon à la poêle",
        "subtitle": "La recette Le secret des tacos au steak de filet mignon à la poêle...",
        "description": "La recette Le secret des tacos au steak de filet mignon à la poêle pourrait satisfaire votre envie mexicaine en 20 minutes environ. Cela fonctionne bien comme plat principal assez cher pour la Saint-Valentin. 3 personnes étaient contentes d'avoir essayé cette recette. Rendez-vous au magasin et procurez-vous de la crème sure, de l'huile d'olive extra vierge, des steaks de filet mignon et quelques autres choses à préparer aujourd'hui. C'est une bonne option si vous suivez un régime sans gluten et cétogène. Il vous est présenté par Pink When. Ce score est solide.",
        "instructions": [
          "Faites chauffer la poêle à feu moyen-doux. Frottez les steaks avec de l'huile d'olive et assaisonnez avec du poivre noir concassé. Faites cuire lentement les filets jusqu'à ce qu'ils atteignent les spécifications souhaitées. Nous aimons cuire le nôtre à point, et cela dure en moyenne environ 7 minutes de chaque côté.",
          "Retirer les filets du feu et les trancher finement et dans le sens de la longueur. Utilisez une poêle propre à feu moyen et réchauffez les tortillas de maïs. Garnir les tortillas de steak, de guacamole, de crème sure et de fromage râpé."
        ]
      }
    },
