    "translations": {
      "en": {
        "title": "Cabbage and sausages in beer",
        "subtitle": "Cabbage and sausages in beer could be just the gluten free and dair...",
        "description": "Cabbage and sausages in beer could be just the gluten free and dairy free recipe you've been looking for. A couple people made this recipe, and 15 would say it hit the spot. It can be enjoyed any time, but it is especially good for Father's Day. A mixture of salt, sugar, cabbage, and a handful of other ingredients are all it takes to make this recipe so tasty. From preparation to the plate, this recipe takes approximately 45 minutes.",
        "instructions": [
          "Melt the butter in a large pan over medium-low heat, add the onion, sugar and salt and cook them, stirring frequently, until the onion is golden, about 5-8 minutes.Stir in the beer, scraping up any bits from the bottom of the pan.",
          "Add the sausages, cabbage and potatoes and simmer, covered, stirring occasionally, for 20 minutes or until the vegetables are tender.",
          "Serve the sausages and veggies in big bowls with plenty of the cooking liquid, sprinkled with freshly cracked pepper."
        ]
      },
      "nl": {
        "title": "Kool en worstjes in bier",
        "subtitle": "Kool en worst in bier is wellicht precies het glutenvrije en zuivel...",
        "description": "Kool en worst in bier is wellicht precies het glutenvrije en zuivelvrije recept waar je naar op zoek was. Een paar mensen hebben dit recept gemaakt, en 15 zouden zeggen dat het een schot in de roos was. Je kunt er op elk moment van genieten, maar het is vooral lekker voor Vaderdag. Een mengsel van zout, suiker, kool en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Smelt de boter in een grote pan op middelhoog vuur, voeg de ui, suiker en zout toe en kook ze, onder regelmatig roeren, tot de ui goudbruin is, ongeveer 5-8 minuten. Roer het bier erdoor en schraap eventuele stukjes van de bodem van de pan.",
          "Voeg de worstjes, de kool en de aardappelen toe en laat afgedekt, af en toe roeren, 20 minuten sudderen, of tot de groenten gaar zijn.",
          "Serveer de worstjes en groenten in grote kommen met veel kookvocht, bestrooid met versgemalen peper."
        ]
      },
      "fr": {
        "title": "Chou et saucisses à la bière",
        "subtitle": "Le chou et les saucisses à la bière pourraient bien être la recette...",
        "description": "Le chou et les saucisses à la bière pourraient bien être la recette sans gluten et sans produits laitiers que vous recherchiez. Quelques personnes ont préparé cette recette, et 15 diraient qu'elle a fait mouche. Il peut être dégusté à tout moment, mais il est particulièrement bon pour la fête des pères. Un mélange de sel, de sucre, de chou et une poignée d’autres ingrédients suffisent pour rendre cette recette si savoureuse. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Faites fondre le beurre dans une grande poêle à feu moyen-doux, ajoutez l'oignon, le sucre et le sel et faites-les revenir, en remuant fréquemment, jusqu'à ce que l'oignon soit doré, environ 5 à 8 minutes. Incorporez la bière en grattant les morceaux du fond de la poêle.",
          "Ajouter les saucisses, le chou et les pommes de terre et laisser mijoter à couvert, en remuant de temps en temps, pendant 20 minutes ou jusqu'à ce que les légumes soient tendres.",
          "Servir les saucisses et les légumes dans de grands bols avec beaucoup de liquide de cuisson, saupoudrés de poivre fraîchement concassé."
        ]
      }
    },
