    "translations": {
      "en": {
        "title": "Crab Salad in Avocado Boats",
        "subtitle": "Crab Salad in Avocado Boats is a gluten free, dairy free, whole 30,...",
        "description": "Crab Salad in Avocado Boats is a gluten free, dairy free, whole 30, and pescatarian main course. This recipe serves 2. 13 people have tried and liked this recipe. From preparation to the plate, this recipe takes about 45 minutes. This score is excellent.",
        "instructions": [
          "Stir red onion, mayonnaise, hot sauce, cilantro, 2 teaspoons lime juice, cumin and lime zest in medium bowl to blend.",
          "Mix in crab meat. Season salad with salt and pepper.",
          "Brush each avocado with the remaining 1 teaspoon lime juice to prevent avocado from browning.",
          "Mound crab salad on each avocado half.",
          "Serve salad with lime wedges."
        ]
      },
      "nl": {
        "title": "Krabsalade in avocadoboten",
        "subtitle": "Krabsalade in Avocado Boats is een glutenvrij, zuivelvrij, geheel 3...",
        "description": "Krabsalade in Avocado Boats is een glutenvrij, zuivelvrij, geheel 30 en pescatarian hoofdgerecht. Dit recept is voor 2 personen. 13 mensen hebben dit recept geprobeerd en vonden het leuk. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Deze score is uitstekend.",
        "instructions": [
          "Roer de rode ui, mayonaise, hete saus, koriander, 2 theelepels limoensap, komijn en limoenschil in een middelgrote kom tot een mengsel.",
          "Krabvlees erdoor mengen. Breng de salade op smaak met peper en zout.",
          "Bestrijk elke avocado met de resterende 1 theelepel limoensap om te voorkomen dat de avocado bruin wordt.",
          "Hoopkrabsalade op elke avocadohelft.",
          "Serveer de salade met partjes limoen."
        ]
      },
      "fr": {
        "title": "Salade de crabe dans des bateaux à l'avocat",
        "subtitle": "La salade de crabe dans les bateaux d'avocat est un plat principal...",
        "description": "La salade de crabe dans les bateaux d'avocat est un plat principal sans gluten, sans produits laitiers, entier 30 et pescatarien. Cette recette est pour 2 personnes. 13 personnes ont essayé et aimé cette recette. De la préparation à l'assiette, cette recette prend environ 45 minutes. Cette note est excellente.",
        "instructions": [
          "Mélanger l'oignon rouge, la mayonnaise, la sauce piquante, la coriandre, 2 cuillères à café de jus de citron vert, le cumin et le zeste de citron vert dans un bol moyen pour mélanger.",
          "Incorporer la chair de crabe. Assaisonner la salade de sel et de poivre.",
          "Badigeonnez chaque avocat avec 1 cuillère à café de jus de citron vert restant pour éviter que l'avocat ne brunisse.",
          "Déposer la salade de crabe sur chaque moitié d'avocat.",
          "Servir la salade avec des quartiers de citron vert."
        ]
      }
    },
