    "translations": {
      "en": {
        "title": "Almond Plum Cake with Creme Fraiche",
        "subtitle": "Almond Plum Cake with Creme Fraiche requires roughly 45 minutes fro...",
        "description": "Almond Plum Cake with Creme Fraiche requires roughly 45 minutes from start to finish. This recipe is liked by 8 foodies and cooks. Head to the store and pick up eggs, baking powder, butter, and a few other things to make it today. This score is solid. Users who liked this recipe also liked Almond Cake with Lemon and Crème Fraîche Glaze, Almond Cake with Lemon and Crème Fraîche Glaze, and Blueberry-Almond Shortcakes with Crème Fraîche.",
        "instructions": [
          ". Preheat the oven at 35",
          "Butter and flour a 9-inch spring form pan. In a small bowl, mix the cake flour with the baking powder and salt.",
          "In a bowl of a standing mixer fitted with a paddle, beat the sugar with the almond paste until crumbly.",
          "Add the butter and beat t high speed until light in color and fluffy, about 2 minutes.",
          "Add the eggs, one at the a time, beating until fully incorporated between additions. Beat the vanilla extract and vanilla seeds. Gently fold in the flour mixture until fully incorporated.",
          "Scrape the batter into the prepared pan. Arrange the plums over the top of the batter.",
          "Bake for 1 hour and 5 minutes, or until the cake is deeply golden and a toothpick inserted in the center comes out clean.",
          "Transfer the cake to a rack and let cool for 15 minutes. Run a knife around the edge of the cake and remove the outside ring of the pan.",
          "Let the cake cool for at least 30 minutes longer.",
          "Serve warm or at room temperature topped with crme fraiche and slivered almonds.Make ahead: The cake can be made one day ahead and stored in an airtight container at room temperature."
        ]
      },
      "nl": {
        "title": "Amandelpruimencake met Creme Fraiche",
        "subtitle": "Amandelpruimentaart met Creme Fraiche heeft van begin tot eind onge...",
        "description": "Amandelpruimentaart met Creme Fraiche heeft van begin tot eind ongeveer 45 minuten nodig. Dit recept is geliefd bij 8 foodies en koks. Ga naar de winkel en koop eieren, bakpoeder, boter en nog een paar andere dingen om het vandaag nog te maken. Deze score is solide. Gebruikers die dit recept lekker vonden, hielden ook van Amandelcake met Citroen en Crème Fraîche Glazuur, Amandelcake met Citroen en Crème Fraîche Glazuur en Bosbessen-Amandel Shortcakes met Crème Fraîche.",
        "instructions": [
          ". Verwarm de oven voor op 35",
          "Boter en bloem een ​​springvorm van 9 inch. Meng in een kleine kom het cakemeel met het bakpoeder en het zout.",
          "Klop in een kom van een staande mixer voorzien van een peddel de suiker met de amandelspijs tot een kruimelig mengsel.",
          "Voeg de boter toe en klop op hoge snelheid tot het licht van kleur en luchtig is, ongeveer 2 minuten.",
          "Voeg de eieren één voor één toe en klop tot ze volledig zijn opgenomen tussen de toevoegingen. Klop het vanille-extract en de vanillezaadjes los. Spatel het bloemmengsel er voorzichtig door tot het volledig is opgenomen.",
          "Schraap het beslag in de voorbereide pan. Verdeel de pruimen over de bovenkant van het beslag.",
          "Bak gedurende 1 uur en 5 minuten, of totdat de cake diep goudbruin is en een tandenstoker die je in het midden steekt er schoon uitkomt.",
          "Breng de cake over naar een rek en laat 15 minuten afkoelen. Ga met een mes langs de rand van de cake en verwijder de buitenste ring van de pan.",
          "Laat de cake minimaal 30 minuten langer afkoelen.",
          "Serveer warm of op kamertemperatuur, bestrooid met crème fraîche en geschaafde amandelen. Vooraf maken: De cake kan een dag van tevoren worden gemaakt en in een luchtdichte verpakking bij kamertemperatuur worden bewaard."
        ]
      },
      "fr": {
        "title": "Gâteau aux amandes et aux prunes avec crème fraîche",
        "subtitle": "Le gâteau aux amandes et aux prunes avec crème fraîche nécessite en...",
        "description": "Le gâteau aux amandes et aux prunes avec crème fraîche nécessite environ 45 minutes du début à la fin. Cette recette est appréciée par 8 gourmets et cuisiniers. Rendez-vous au magasin et récupérez des œufs, de la levure chimique, du beurre et quelques autres choses pour le préparer aujourd'hui. Ce score est solide. Les utilisateurs qui ont aimé cette recette ont également aimé Gâteau aux amandes avec glaçage au citron et crème fraîche, Gâteau aux amandes avec glaçage au citron et crème fraîche et Shortcakes myrtilles-amandes avec crème fraîche.",
        "instructions": [
          ". Préchauffer le four à 35",
          "Beurrer et fariner un moule à charnière de 9 pouces. Dans un petit bol, mélangez la farine à gâteau avec la levure chimique et le sel.",
          "Dans le bol d'un batteur sur pied muni d'une pale, battre le sucre avec la pâte d'amande jusqu'à obtenir un mélange grumeleux.",
          "Ajouter le beurre et battre à haute vitesse jusqu'à ce qu'il soit clair et mousseux, environ 2 minutes.",
          "Ajouter les œufs, un à la fois, en battant jusqu'à ce qu'ils soient complètement incorporés entre les ajouts. Battez l'extrait de vanille et les graines de vanille. Incorporer délicatement le mélange de farine jusqu'à ce qu'il soit complètement incorporé.",
          "Versez la pâte dans le moule préparé. Disposez les prunes sur la pâte.",
          "Cuire au four pendant 1 heure et 5 minutes, ou jusqu'à ce que le gâteau soit bien doré et qu'un cure-dent inséré au centre en ressorte propre.",
          "Transférer le gâteau sur une grille et laisser refroidir 15 minutes. Passez un couteau sur le pourtour du gâteau et retirez l'anneau extérieur du moule.",
          "Laissez le gâteau refroidir au moins 30 minutes de plus.",
          "Servir chaud ou à température ambiante garni de crème fraîche et d'amandes effilées. Préparez à l'avance : Le gâteau peut être préparé un jour à l'avance et conservé dans un récipient hermétique à température ambiante."
        ]
      }
    },
