        "description": "Les crevettes grillées à l'ail et aux herbes prennent environ 45 minutes du début à la fin. Pour 64 centimes la portion, vous obtenez un hor-d'œuvre pour 4 personnes. Vous surveillez votre silhouette ? 11 personnes étaient heureuses d’avoir essayé cette recette. Un mélange de flocons de piment, d'ail, de zeste de citron et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. C’est parfait pour le 4 juillet.",
