        "description": "La salade de figues, de chèvre et de noix nécessite environ 15 minutes du début à la fin. 3 personnes ont réalisé cette recette et la referaient. Si vous avez de l’huile d’olive, des légumes verts, du jus de citron et quelques autres ingrédients sous la main, vous pouvez le préparer. Cela fonctionne bien comme un hor d'œuvre. Ce score est solide. Si vous aimez cette recette, vous aimerez peut-être aussi des recettes comme Salade de figues et chèvre avec vinaigrette balsamique aux figues, Salade de chèvre frit et figues et Salade de figues séchées, chèvre et roquette.",
