    "image": "images/spoonacular-634191.jpg",
    "isGlutenFree": false,
    "isNutFree": false,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": false,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Banana Split Sundae Ice Cream Cake",
        "subtitle": "You can never have too many dessert recipes, so give Banana Split S...",
        "description": "You can never have too many dessert recipes, so give Banana Split Sundae Ice Cream Cake a try. This recipe serves 18. From preparation to the plate, this recipe takes roughly 45 minutes. Head to the store and pick up whipped topping, butter, bananas, and a few other things to make it today. It is perfect for Summer.",
        "instructions": [
          "In a small bowl, combine the graham cracker crumbs and the melted butter.  Set aside 1/4 cup of the mixture then press the remainder into the bottom of a 9 x 13 pan.",
          "Place the bananas in a single layer over the crust.",
          "Spread the softened ice cream on top and smooth.",
          "Sprinkle the nuts on the ice cream, then cover with plastic wrap and freeze until firm, about 2 hours.",
          "In a medium saucepan, melt the chocolate chips and the remaining 1/4 cup butter and stir until smooth.",
          "Add the confectioner's sugar and evaporated milk.  Cook, stirring constantly over medium heat until slightly thickened and smooth, about 8 minutes.",
          "Remove the pan from the heat and stir in vanilla.  Cool the mixture about 30 minutes stirring occasionally.",
          "Pour the mixture over the ice cream and freeze until firm, about 1 hour.",
          "Spread the whipped topping over the chocolate layer and sprinkle with reserved crumbs.  Freeze for at least 4 hours or overnight.",
          "Remove from freezer 20 minutes before serving."
        ]
      },
      "nl": {
        "title": "Bananensplit-ijstaart met ijscoupes",
        "subtitle": "Je kunt nooit genoeg dessertrecepten hebben, dus probeer Banana Spl...",
        "description": "Je kunt nooit genoeg dessertrecepten hebben, dus probeer Banana Split Sundae Ice Cream Cake eens. Dit recept is voor 18 personen. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Ga naar de winkel en koop slagroom, boter, bananen en nog een paar andere dingen om het vandaag nog te maken. Het is perfect voor de zomer.",
        "instructions": [
          "Meng in een kleine kom de crackerkruimels van Graham en de gesmolten boter.  Zet 1/4 kopje van het mengsel opzij en druk de rest op de bodem van een pan van 9 x 13 cm.",
          "Leg de bananen in een enkele laag over de korst.",
          "Verdeel het zachte ijs erover en strijk glad.",
          "Strooi de noten over het ijs, dek het af met plasticfolie en vries het in tot het stevig is, ongeveer 2 uur.",
          "Smelt de chocoladestukjes en de resterende 1/4 kop boter in een middelgrote pan en roer tot een gladde massa.",
          "Voeg de suiker van de banketbakker en de verdampte melk toe.  Kook, onder voortdurend roeren op middelhoog vuur, tot het iets dikker en gladder is, ongeveer 8 minuten.",
          "Haal de pan van het vuur en roer de vanille erdoor.  Laat het mengsel ongeveer 30 minuten afkoelen, af en toe roerend.",
          "Giet het mengsel over het ijs en vries het in tot het stevig is, ongeveer 1 uur.",
          "Verdeel de opgeklopte topping over de chocoladelaag en bestrooi met achtergehouden kruimels.  Zet het minimaal 4 uur of een hele nacht in de vriezer.",
          "Haal 20 minuten voor het serveren uit de vriezer."
        ]
      },
      "fr": {
        "title": "Gâteau à la crème glacée à la banane fendue",
        "subtitle": "Vous ne pouvez jamais avoir trop de recettes de desserts, alors ess...",
        "description": "Vous ne pouvez jamais avoir trop de recettes de desserts, alors essayez le gâteau à la crème glacée Banana Split Sundae. Cette recette en sert 18 personnes. De la préparation à l'assiette, cette recette prend environ 45 minutes. Rendez-vous au magasin et procurez-vous de la garniture fouettée, du beurre, des bananes et quelques autres choses à préparer aujourd'hui. 18 personnes ont réalisé cette recette et la referaient. C'est parfait pour l'été.",
        "instructions": [
          "Dans un petit bol, mélanger la chapelure de biscuits Graham et le beurre fondu.  Réserver 1/4 tasse du mélange puis presser le reste au fond d'un moule 9 x 13.",
          "Disposez les bananes en une seule couche sur la croûte.",
          "Étalez dessus la glace ramollie et lissez.",
          "Saupoudrer les noix sur la glace, puis couvrir d'une pellicule plastique et congeler jusqu'à ce qu'elles soient fermes, environ 2 heures.",
          "Dans une casserole moyenne, faire fondre les pépites de chocolat et le 1/4 tasse de beurre restant et remuer jusqu'à consistance lisse.",
          "Ajouter le sucre glace et le lait concentré.  Cuire en remuant constamment à feu moyen jusqu'à ce que le mélange soit légèrement épaissi et lisse, environ 8 minutes.",
          "Retirez la casserole du feu et incorporez la vanille.  Refroidissez le mélange environ 30 minutes en remuant de temps en temps.",
          "Versez le mélange sur la glace et congelez jusqu'à ce qu'il soit ferme, environ 1 heure.",
          "Étalez la garniture fouettée sur la couche de chocolat et saupoudrez de chapelure réservée.  Congeler pendant au moins 4 heures ou toute la nuit.",
          "Sortir du congélateur 20 minutes avant de servir."
        ]
      }
    },
