    "image": "images/spoonacular-632539.jpg",
    "isGlutenFree": false,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
    "isKeto": false,
    "translations": {
      "en": {
        "title": "Apple Dumplings In Fanta Sauce",
        "subtitle": "Apple Dumplings In Fanta Sauce is a lacto ovo vegetarian sauce.",
        "description": "Apple Dumplings In Fanta Sauce is a lacto ovo vegetarian sauce. This recipe serves 16. Not a lot of people made this recipe, and 2 would say it hit the spot. Head to the store and pick up fanta lemon, apples, juice of lemon, and a few other things to make it today. From preparation to the plate, this recipe takes approximately 45 minutes.",
        "instructions": [
          "Preheat oven to 400 F (abouyt 200 C).",
          "Peel and core the apples and cut into crescents  firstly cut each apple into 4 pieces and then cut each of those into 2 pieces.",
          "Sprinkle with lemon juice.",
          "Cut with a sharp knife the puff pastry into equal squares (each crust into 4), and afterwards into triangles - 8 triangles from each crust.",
          "Put a crescent of apple into a puff pastry triangle.",
          "Roll up to the top.",
          "In a different pan melt butter, add sugar and essence and stir well.",
          "Arrange dumplings in a baking pan, close enough to each other, and pour plenty of melted butter and sugar on each of them.",
          "Pour upon with Fanta.",
          "Sprinkle with grounded cinnamon (optional).",
          "Bake into preheated to 400 F (about 200 C) oven for about 30 minutes, as after the first 15-20 minutes may cover with baking paper, so the dumplings would not burn."
        ]
      },
      "nl": {
        "title": "Appelknoedels In Fantasaus",
        "subtitle": "Appelknoedels In Fantasaus is een lacto ovo vegetarische saus.",
        "description": "Appelknoedels In Fantasaus is een lacto ovo vegetarische saus. Dit recept serveert 16 personen. Niet veel mensen hebben dit recept gemaakt, en 2 zouden zeggen dat het een schot in de roos was. Ga naar de winkel en koop fanta-citroen, appels, citroensap en nog een paar andere dingen om het vandaag te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Verwarm de oven voor op 400 F (ongeveer 200 C).",
          "Schil de appels, verwijder het klokhuis en snijd ze in halve manen. Snijd elke appel eerst in 4 stukken en vervolgens elk van deze in 2 stukken.",
          "Besprenkel met citroensap.",
          "Snij met een scherp mes het bladerdeeg in gelijke vierkanten (elke korst in 4), en daarna in driehoeken - 8 driehoeken van elke korst.",
          "Doe een halve appel in een bladerdeegdriehoek.",
          "Rol op naar de bovenkant.",
          "Smelt de boter in een andere pan, voeg suiker en essence toe en roer goed.",
          "Schik de dumplings in een bakvorm, dicht genoeg bij elkaar, en giet er voldoende gesmolten boter en suiker over.",
          "Giet op met Fanta.",
          "Bestrooi met gemalen kaneel (optioneel).",
          "Bak in een voorverwarmde oven van 400 F (ongeveer 200 C) gedurende ongeveer 30 minuten, want na de eerste 15-20 minuten mag je de dumplings afdekken met bakpapier, zodat de dumplings niet verbranden."
        ]
      },
      "fr": {
        "title": "Boulettes De Pommes à La Sauce Fanta",
        "subtitle": "Les raviolis aux pommes en sauce Fanta sont une sauce lacto-ovo-vég...",
        "description": "Les raviolis aux pommes en sauce Fanta sont une sauce lacto-ovo-végétarienne. Cette recette en sert 16 personnes. Peu de gens ont fait cette recette, et 2 diraient qu’elle a fait mouche. Rendez-vous au magasin et procurez-vous du citron fanta, des pommes, du jus de citron et quelques autres choses à préparer aujourd'hui. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Préchauffer le four à 400 F (environ 200 C).",
          "Épluchez et épépinez les pommes et coupez-les en croissants. Coupez d'abord chaque pomme en 4 morceaux, puis coupez chacune d'elles en 2 morceaux.",
          "Arrosez de jus de citron.",
          "Coupez avec un couteau bien aiguisé la pâte feuilletée en carrés égaux (chaque croûte en 4), puis en triangles - 8 triangles pour chaque croûte.",
          "Disposez un croissant de pomme dans un triangle de pâte feuilletée.",
          "Roulez vers le haut.",
          "Dans une autre poêle, faire fondre le beurre, ajouter le sucre et l'essence et bien mélanger.",
          "Disposez les boulettes dans un plat allant au four, suffisamment proches les unes des autres, et versez beaucoup de beurre fondu et de sucre sur chacune d'elles.",
          "Versez avec Fanta.",
          "Saupoudrer de cannelle moulue (facultatif).",
          "Cuire au four préchauffé à 400 F (environ 200 C) pendant environ 30 minutes, car après les 15 à 20 premières minutes, vous pouvez recouvrir de papier sulfurisé pour que les boulettes ne brûlent pas."
        ]
      }
    },
