    "translations": {
      "en": {
        "title": "Double Chocolate Milo Pancakes",
        "subtitle": "Double Chocolate Milo Pancakes takes approximately 45 minutes from...",
        "description": "Double Chocolate Milo Pancakes takes approximately 45 minutes from beginning to end. 6 people were glad they tried this recipe. Head to the store and pick up flour, sugar, sugar, and a few other things to make it today. It works well as a very reasonably priced breakfast. It is a good option if you're following a lacto ovo vegetarian diet. It is brought to you by Afrolems.",
        "instructions": [
          "Mix your dry ingredients and wet ingredients except the peanuts till smooth.In a pan, add 1 tablespoon of vegetable oil and with a small spoon, scoop the mixture and form little circles in the pan.Fry on low- medium heat till brown on both sides.When pancakes are fried and ready set aside.In a small pan, mix the milo, sugar and water and bring to boil on medium heat till a thick sauce is formed.",
          "Pour into a bowl and allow to cool.Crush your peanuts and set aside.With a tiny scoop of the chocolate syrup, smear it over the pancakes and sprinkle some peanuts over it.When they are all ready, dust it over with a bit more milo and serve."
        ]
      },
      "nl": {
        "title": "Dubbele chocolade Milo-pannenkoeken",
        "subtitle": "Double Chocolate Milo Pancakes duurt ongeveer 45 minuten van begin...",
        "description": "Double Chocolate Milo Pancakes duurt ongeveer 45 minuten van begin tot eind. 6 mensen waren blij dat ze dit recept probeerden. Ga naar de winkel en koop meel, suiker, suiker en nog een paar andere dingen om het vandaag nog te maken. Het werkt goed als een zeer redelijk geprijsd ontbijt. Het is een goede optie als je een lacto-ovo-vegetarisch dieet volgt. It is brought to you by Afrolems. Galletas de Milo (Milo-koekjes), PB-pannenkoeken met dubbele chocolade en dubbele chocoladepannenkoeken lijken sterk op dit recept.",
        "instructions": [
          "Meng de droge ingrediënten en de natte ingrediënten behalve de pinda's tot een gladde massa. Voeg 1 eetlepel plantaardige olie toe in een pan en schep het mengsel met een kleine lepel op en vorm kleine cirkels in de pan. Bak op laag tot middelhoog vuur tot ze aan beide kanten bruin zijn. Als de pannenkoeken gebakken en klaar zijn, zet ze dan opzij. Meng de milo, de suiker en het water in een kleine pan en breng op middelhoog vuur aan de kook tot er een dikke saus ontstaat.",
          "Giet het mengsel in een kom en laat afkoelen. Verpletter de pinda's en zet opzij. Smeer dit met een klein schepje chocoladesiroop over de pannenkoekjes en strooi er wat pinda's over. Als ze allemaal klaar zijn bestrooi je ze met nog wat milo en serveer."
        ]
      },
      "fr": {
        "title": "Crêpes Milo Double Chocolat",
        "subtitle": "Les crêpes Milo au double chocolat prennent environ 45 minutes du d...",
        "description": "Les crêpes Milo au double chocolat prennent environ 45 minutes du début à la fin. 6 personnes étaient contentes d'avoir essayé cette recette. Rendez-vous au magasin et récupérez de la farine, du sucre, du sucre et quelques autres éléments pour le préparer aujourd'hui. Cela fonctionne bien comme petit-déjeuner à un prix très raisonnable. C'est une bonne option si vous suivez un régime lacto-ovo-végétarien. Il vous est présenté par Afrolems.",
        "instructions": [
          "Mélangez vos ingrédients secs et vos ingrédients humides, sauf les cacahuètes, jusqu'à consistance lisse. Dans une poêle, ajoutez 1 cuillère à soupe d'huile végétale et avec une petite cuillère, versez le mélange et formez des petits cercles dans la poêle. Faites frire à feu doux-moyen jusqu'à ce qu'ils soient dorés des deux côtés.",
          "Versez dans un bol et laissez refroidir. Concassez vos cacahuètes et réservez. Avec une petite boule de sirop de chocolat, étalez-en sur les crêpes et saupoudrez-les de cacahuètes. Quand elles sont toutes prêtes, saupoudrez-les d'un peu plus de milo et servez."
        ]
      }
    },
