        "subtitle": "You can never have too many main course recipes, so give Easy Tomat...",
        "description": "You can never have too many main course recipes, so give Easy Tomato Basil Chicken – One Pot Meal a try. This recipe serves 6. Watching your figure? 10 people have tried and liked this recipe. It is brought to you by Pink When. Head to the store and pick up basil, rotini pasta, chicken breast strips/pre-cooked/chopped, and a few other things to make it today. From preparation to the plate, this recipe takes around 30 minutes. This score is solid.",
