        "description": "Je kunt nooit genoeg hoofdgerechtrecepten hebben, dus probeer Easy Tomato Basil Chicken – One Pot Meal eens. Dit recept is voor 6 personen. Op je figuur letten? 10 mensen hebben dit recept geprobeerd en vonden het leuk. Het wordt u aangeboden door Pink When. Ga naar de winkel en koop basilicum, rotini-pasta, kipfiletreepjes/voorgekookt/gehakt en nog een paar andere dingen om het vandaag te maken. Van bereiding tot op het bord duurt dit recept ongeveer 30 minuten. Deze score is solide.",
