    "translations": {
      "en": {
        "title": "Ground Turkey Stuffed Peppers",
        "subtitle": "Ground Turkey Stuffed Peppers might be just the main course you are...",
        "description": "Ground Turkey Stuffed Peppers might be just the main course you are searching for. Watching your figure? 112 people were glad they tried this recipe. A mixture of bell peppers, garlic, onion, and a handful of other ingredients are all it takes to make this recipe so yummy. From preparation to the plate, this recipe takes roughly 45 minutes.",
        "instructions": [
          "Cook rice then knead it together with remaining filling ingredients.",
          "Cut tops off peppers and fill each one.",
          "Place in your slow cooker or a large stove-top pot.",
          "Mix together sauce ingredients. Top each stuffed pepper with sauce and pour remaining sauce all around the stuffed peppers. Cook on medium/low for about an hour. Top with grated parmesan cheese and a little parsley for looks and serve warm."
        ]
      },
      "nl": {
        "title": "Gemalen kalkoen gevulde paprika's",
        "subtitle": "Gemalen Kalkoen Gevulde Paprika's is misschien wel het hoofdgerecht...",
        "description": "Gemalen Kalkoen Gevulde Paprika's is misschien wel het hoofdgerecht waar u naar op zoek bent. Op je figuur letten? 112 mensen waren blij dat ze dit recept probeerden. Een mengsel van paprika, knoflook, ui en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Kook de rijst en kneed het samen met de resterende ingrediënten voor de vulling.",
          "Snij het kapje van de paprika's en vul ze allemaal.",
          "Plaats het in uw slowcooker of een grote kookplaat.",
          "Meng de sausingrediënten door elkaar. Bestrijk elke gevulde paprika met saus en giet de resterende saus rondom de gevulde paprika's. Kook ongeveer een uur op medium/laag. Bestrooi met geraspte Parmezaanse kaas en een beetje peterselie voor de look en serveer warm."
        ]
      },
      "fr": {
        "title": "Poivrons farcis à la dinde hachée",
        "subtitle": "Les poivrons farcis à la dinde hachée pourraient bien être le plat...",
        "description": "Les poivrons farcis à la dinde hachée pourraient bien être le plat principal que vous recherchez. Vous surveillez votre silhouette ? 112 personnes étaient heureuses d'avoir essayé cette recette. Un mélange de poivrons, d’ail, d’oignon et une poignée d’autres ingrédients suffisent pour rendre cette recette si délicieuse. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Faites cuire le riz puis pétrissez-le avec le reste des ingrédients de la garniture.",
          "Coupez le dessus des poivrons et remplissez chacun d'eux.",
          "Placez-le dans votre mijoteuse ou dans une grande marmite sur la cuisinière.",
          "Mélanger les ingrédients de la sauce. Garnir chaque poivron farci de sauce et verser le reste de la sauce tout autour des poivrons farcis. Cuire à feu moyen/doux pendant environ une heure. Garnir de parmesan râpé et d'un peu de persil pour l'aspect et servir chaud."
        ]
      }
    },
