    "translations": {
      "en": {
        "title": "Oxtail Ragout",
        "subtitle": "Oxtail Ragout takes about 45 minutes from beginning to end.",
        "description": "Oxtail Ragout takes about 45 minutes from beginning to end. This recipe serves 4. Only a few people made this recipe, and 3 would say it hit the spot. It works well as a main course. A mixture of oxtails, tomato juice, flour, and a handful of other ingredients are all it takes to make this recipe so delicious. It is a good option if you're following a dairy free diet.",
        "instructions": [
          "Combine 1 teaspoon of salt, pepper, paprika, and flour.",
          "Roll oxtails in seasoned flour, brown thoroughly in hot fat.",
          "Add remaining ingredientsexcept lemon juice. Cover, simmer 3 hours,",
          "Remove allspice and bay leaf.",
          "Serve with hot, buttered noodles. Good with rice too."
        ]
      },
      "nl": {
        "title": "Ragout van ossenstaart",
        "subtitle": "Ossenstaartragout duurt van begin tot eind ongeveer 45 minuten.",
        "description": "Ossenstaartragout duurt van begin tot eind ongeveer 45 minuten. Dit recept is voor 4 personen. Slechts een paar mensen hebben dit recept gemaakt, en drie zouden zeggen dat het een succes was. Het werkt goed als hoofdgerecht. Een mengsel van ossenstaarten, tomatensap, bloem en een handvol andere ingrediënten is voldoende om dit recept zo heerlijk te maken. Het is een goede optie als u een zuivelvrij dieet volgt.",
        "instructions": [
          "Combineer 1 theelepel zout, peper, paprikapoeder en bloem.",
          "Rol de ossenstaartjes door de gekruide bloem en bak ze goed bruin in heet vet.",
          "Voeg de resterende ingrediënten toe, behalve citroensap. Dek af, laat 3 uur sudderen,",
          "Verwijder piment en laurierblad.",
          "Serveer met warme, beboterde noedels. Ook lekker met rijst."
        ]
      },
      "fr": {
        "title": "Ragoût de queue de bœuf",
        "subtitle": "Oxtail Ragout prend environ 45 minutes du début à la fin.",
        "description": "Oxtail Ragout prend environ 45 minutes du début à la fin. Cette recette en sert 4. Seules quelques personnes ont fait cette recette, et 3 diraient qu’elle a fait mouche. Cela fonctionne bien comme plat principal. Un mélange de queues de bœuf, de jus de tomate, de farine et une poignée d'autres ingrédients suffisent pour rendre cette recette si délicieuse. C'est une bonne option si vous suivez un régime sans produits laitiers.",
        "instructions": [
          "Mélangez 1 cuillère à café de sel, poivre, paprika et farine.",
          "Rouler les queues de bœuf dans la farine assaisonnée, les faire dorer soigneusement dans la graisse chaude.",
          "Ajouter le reste des ingrédients, sauf le jus de citron. Couvrir, laisser mijoter 3 heures,",
          "Retirez le piment de la Jamaïque et la feuille de laurier.",
          "Servir avec des nouilles chaudes beurrées. Bon aussi avec du riz."
        ]
      }
    },
