    "image": "images/spoonacular-652886.jpg",
    "isGlutenFree": true,
    "isNutFree": true,
    "isDairyFree": false,
    "isEggFree": true,
    "isVegetarian": true,
    "isVegan": false,
    "isCandidaFriendly": false,
