    "translations": {
      "en": {
        "title": "My Sister's Soup: Creamy Curried Squash and Cauliflower Soup",
        "subtitle": "My Sister's Soup: Creamy Curried Squash and Cauliflower Soup is a g...",
        "description": "My Sister's Soup: Creamy Curried Squash and Cauliflower Soup is a gluten free, lacto ovo vegetarian, and primal hor d'oeuvre. This recipe serves 6. If you have garlic, delicata squash, butter, and a few other ingredients on hand, you can make it. Autumn will be even more special with this recipe. From preparation to the plate, this recipe takes about 45 minutes.",
        "instructions": [
          "Preheat your oven to 375 degrees F.",
          "Slice the squash length wise and place face down in a casserole dish with about 1/4\" water on the bottom.",
          "Bake for about 30 minutes or until the squash is tender. Cool a bit, then when you can touch the squash, scoop out the seeds.  Scoop the squash flesh into a bowl and set aside.",
          "In a large stock pot, heat the butter and saut the onions over low-to-medium heat until theyre translucent.",
          "Add the garlic, curry powder, red pepper flakes and salt and pepper to the onion.",
          "Add the squash and cauliflower into the pot along with the stock, and simmer for about 20 minutes.",
          "Puree the squash and cauliflower (along with the liquid) in batches in a blender.",
          "Add a bit more stock (a little at a time) if you think the mixture is too thick.",
          "Transfer the soup to bowls and serve with a dollop of sour cream."
        ]
      },
      "nl": {
        "title": "My Sister's Soup: Romige curry-pompoen- en bloemkoolsoep",
        "subtitle": "My Sister's Soup: Romige Curried Squash en Bloemkoolsoep is een glu...",
        "description": "My Sister's Soup: Romige Curried Squash en Bloemkoolsoep is een glutenvrije, lacto ovo-vegetarische en oer-hor d'oeuvre. Dit recept is voor 6 personen. Als je knoflook, delicatapompoen, boter en een paar andere ingrediënten bij de hand hebt, kun je het maken. De herfst wordt nog specialer met dit recept. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten.",
        "instructions": [
          "Verwarm uw oven voor op 375 graden F.",
          "Snijd de pompoen in de lengte door en plaats deze met de voorkant naar beneden in een ovenschaal met ongeveer 1/4 \"water op de bodem.",
          "Bak ongeveer 30 minuten of tot de pompoen gaar is. Laat het een beetje afkoelen, en als je de pompoen kunt aanraken, schep je de zaden eruit.  Schep het vruchtvlees van de pompoen in een kom en zet opzij.",
          "Verhit de boter in een grote soeppan en bak de uien op laag tot middelhoog vuur tot ze doorschijnend zijn.",
          "Voeg de knoflook, kerriepoeder, rode pepervlokken en zout en peper toe aan de ui.",
          "Doe de pompoen en de bloemkool samen met de bouillon in de pan en laat ongeveer 20 minuten koken.",
          "Pureer de pompoen en bloemkool (samen met de vloeistof) in batches in een blender.",
          "Voeg eventueel nog wat bouillon toe (beetje voor beetje) als je het mengsel te dik vindt.",
          "Doe de soep in kommen en serveer met een klodder zure room."
        ]
      },
      "fr": {
        "title": "Soupe de ma sœur : soupe crémeuse à la courge et au chou-fleur au curry",
        "subtitle": "Soupe de ma sœur : La soupe crémeuse à la courge et au chou-fleur a...",
        "description": "Soupe de ma sœur : La soupe crémeuse à la courge et au chou-fleur au curry est un hors-d'œuvre sans gluten, lacto ovo végétarien et primal. Cette recette est pour 6 personnes. 2 personnes ont réalisé cette recette et la referaient. Si vous avez de l’ail, de la courge delicata, du beurre et quelques autres ingrédients sous la main, vous pouvez le préparer. L'automne sera encore plus spécial avec cette recette. De la préparation à l'assiette, cette recette prend environ 45 minutes.",
        "instructions": [
          "Préchauffez votre four à 375 degrés F.",
          "Coupez la courge dans le sens de la longueur et placez-la face vers le bas dans une cocotte avec environ 1/4\" d'eau au fond.",
          "Cuire au four environ 30 minutes ou jusqu'à ce que la courge soit tendre. Laissez refroidir un peu, puis lorsque vous pouvez toucher la courge, retirez les graines.  Versez la chair de courge dans un bol et réservez.",
          "Dans une grande marmite, faites chauffer le beurre et faites revenir les oignons à feu doux à moyen jusqu'à ce qu'ils soient translucides.",
          "Ajoutez l'ail, la poudre de curry, les flocons de piment rouge, le sel et le poivre à l'oignon.",
          "Ajoutez la courge et le chou-fleur dans la casserole avec le bouillon et laissez mijoter environ 20 minutes.",
          "Réduisez en purée la courge et le chou-fleur (avec le liquide) par lots dans un mélangeur.",
          "Ajoutez un peu plus de bouillon (petit à petit) si vous pensez que le mélange est trop épais.",
          "Transférer la soupe dans des bols et servir avec une cuillerée de crème sure."
        ]
      }
    },
