    "translations": {
      "en": {
        "title": "Mediterranean Herb Dip",
        "subtitle": "Need a gluten free hor d'oeuvre?",
        "description": "Need a gluten free hor d'oeuvre? Mediterranean Herb Dip could be an awesome recipe to try. 11 person found this recipe to be scrumptious and satisfying. If you have tabasco hot sauce, bar of cream cheese, garlic cloves, and a few other ingredients on hand, you can make it. From preparation to the plate, this recipe takes around 45 minutes. The Super Bowl will be even more special with this recipe. If you like this recipe, you might also like recipes such as Mediterranean Herb Rub, Herb-Roasted Mediterranean Vegetables, and Mediterranean Herb Baked Chicken.",
        "instructions": [
          "Put the sun dried tomatoes, roasted red peppers and garlic in a food processor. Pulse until finely chopped.",
          "Add the feta cheese, cream cheese, Worcestershire sauce and Tabasco. Pulse until combined.",
          "Add parsley and basil. Pulse again until combined.**Keep refrigerated."
        ]
      },
      "nl": {
        "title": "Mediterrane kruidendip",
        "subtitle": "Een glutenvrij hor d'oeuvre nodig?",
        "description": "Een glutenvrij hor d'oeuvre nodig? Mediterrane Kruidendip zou een geweldig recept kunnen zijn om te proberen. 11 personen vonden dit recept heerlijk en bevredigend. Als je tabasco-hete saus, een reep roomkaas, knoflookteentjes en een paar andere ingrediënten bij de hand hebt, kun je het maken. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Met dit recept wordt de Super Bowl nog specialer. Als je dit recept lekker vindt, hou je misschien ook wel van recepten als Mediterrane Kruidenwrijven, Met Kruiden Geroosterde Mediterrane Groenten en Mediterrane Kruidengebakken Kip.",
        "instructions": [
          "Doe de zongedroogde tomaten, geroosterde rode paprika en knoflook in een keukenmachine. Pulseer tot het fijngehakt is.",
          "Voeg de fetakaas, roomkaas, Worcestershiresaus en Tabasco toe. Pulseer tot het gecombineerd is.",
          "Voeg peterselie en basilicum toe. Pulseer opnieuw tot alles gemengd is. **Bewaar in de koelkast."
        ]
      },
      "fr": {
        "title": "Trempette aux herbes méditerranéennes",
        "subtitle": "Besoin d'un hors-d'œuvre sans gluten ?",
        "description": "Besoin d'un hors-d'œuvre sans gluten ? La trempette méditerranéenne aux herbes pourrait être une recette géniale à essayer. 11 personnes ont trouvé cette recette délicieuse et satisfaisante. Si vous avez de la sauce piquante tabasco, une barre de fromage à la crème, des gousses d'ail et quelques autres ingrédients sous la main, vous pouvez la préparer. De la préparation à l'assiette, cette recette prend environ 45 minutes. Le Super Bowl sera encore plus spécial avec cette recette. Si vous aimez cette recette, vous aimerez peut-être également des recettes telles que Rub à base d'herbes méditerranéennes, Légumes méditerranéens rôtis aux herbes et Poulet cuit au four aux herbes méditerranéennes.",
        "instructions": [
          "Mettez les tomates séchées au soleil, les poivrons rouges rôtis et l'ail dans un robot culinaire. Pulser jusqu'à ce qu'il soit finement haché.",
          "Ajouter le fromage feta, le fromage à la crème, la sauce Worcestershire et le Tabasco. Pulser jusqu'à ce que le tout soit combiné.",
          "Ajouter le persil et le basilic. Pulser à nouveau jusqu'à ce que le tout soit combiné.**Conserver au réfrigérateur."
        ]
      }
    },
