    "translations": {
      "en": {
        "title": "Orange Chocolate Cake",
        "subtitle": "Orange Chocolate Cake requires approximately 45 minutes from start...",
        "description": "Orange Chocolate Cake requires approximately 45 minutes from start to finish. A mixture of semi-sweet chocolate, baking soda, flour, and a handful of other ingredients are all it takes to make this recipe so tasty. A few people really liked this dessert.",
        "instructions": [
          "Preheat oven at 175C, Grease a 9\" bundt pan, and dust flour or spray non-stick spray in pan.Beat butter for a while and add in sugar, continue to beat butter until creamy.",
          "Add eggs one at a time and mix well.",
          "Add orange rind, orange juice and vanilla extract, beat at low speed till well combined.Split ingredient (B) into 4 portions and sour cream into 3 portions.",
          "Pour in one portion of flour and sour cream alternately, beat well after each addition.Take half of the mixture and gently mix with melted chocolate (do not over mix).Scoop plain and chocolate batter alternately into pan, till all the batters are used up and gently shake the pan a little.",
          "Bake for 50-60 minutes or skewer comes out clean.",
          "Remove cake from oven and set to cool for 20 minutes then unmould, leave to cool completely."
        ]
      },
      "nl": {
        "title": "Oranje chocoladetaart",
        "subtitle": "De Orange Chocolate Cake heeft van begin tot eind ongeveer 45 minut...",
        "description": "De Orange Chocolate Cake heeft van begin tot eind ongeveer 45 minuten nodig. Een mengsel van halfzoete chocolade, zuiveringszout, bloem en een handvol andere ingrediënten is voldoende om dit recept zo lekker te maken. Een paar mensen vonden dit dessert erg lekker.",
        "instructions": [
          "Verwarm de oven voor op 175 ° C. Vet een 23 cm grote pan in en bestuif bloem of spuit antiaanbakspray in de pan. Klop de boter een tijdje en voeg de suiker toe, blijf de boter kloppen tot hij romig is.",
          "Voeg de eieren één voor één toe en meng goed.",
          "Voeg de sinaasappelschil, het sinaasappelsap en het vanille-extract toe en klop op lage snelheid tot alles goed gemengd is. Verdeel ingrediënt (B) in 4 porties en de zure room in 3 porties.",
          "Giet afwisselend een portie bloem en zure room erbij en klop goed na elke toevoeging. Neem de helft van het mengsel en meng voorzichtig met gesmolten chocolade (niet te lang mixen). Schep het pure beslag en het chocoladebeslag afwisselend in de pan, tot al het beslag op is en schud de pan voorzichtig een beetje.",
          "Bak gedurende 50-60 minuten, anders komt de satéprikker er schoon uit.",
          "Haal de cake uit de oven en laat hem 20 minuten afkoelen, haal hem dan uit de vorm en laat hem volledig afkoelen."
        ]
      },
      "fr": {
        "title": "Gâteau au chocolat et à l'orange",
        "subtitle": "Le gâteau au chocolat et à l'orange nécessite environ 45 minutes du...",
        "description": "Le gâteau au chocolat et à l'orange nécessite environ 45 minutes du début à la fin. 95 personnes ont réalisé cette recette et la referaient. Un mélange de chocolat mi-sucré, de bicarbonate de soude, de farine et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse. Quelques personnes ont vraiment aimé ce dessert.",
        "instructions": [
          "Préchauffer le four à 175°C, graisser un moule à gâteau de 9\" et saupoudrer de farine ou vaporiser un spray antiadhésif dans le moule. Battre le beurre pendant un moment et ajouter le sucre, continuer à battre le beurre jusqu'à ce qu'il soit crémeux.",
          "Ajoutez les œufs un à un et mélangez bien.",
          "Ajouter le zeste d'orange, le jus d'orange et l'extrait de vanille, battre à basse vitesse jusqu'à ce que le tout soit bien mélangé. Diviser l'ingrédient (B) en 4 portions et la crème sure en 3 portions.",
          "Versez alternativement une portion de farine et de crème sure, battez bien après chaque ajout. Prenez la moitié du mélange et mélangez délicatement avec le chocolat fondu (ne pas trop mélanger). Versez alternativement la pâte nature et la pâte au chocolat dans la poêle jusqu'à épuisement de la pâte et secouez doucement la poêle.",
          "Cuire au four pendant 50 à 60 minutes ou la brochette en ressort propre.",
          "Sortir le gâteau du four et laisser refroidir 20 minutes puis démouler et laisser refroidir complètement."
        ]
      }
    },
