    "translations": {
      "en": {
        "title": "Chicken Lo Mein",
        "subtitle": "Chicken Lo Mein is a dairy free recipe with 2 servings.",
        "description": "Chicken Lo Mein is a dairy free recipe with 2 servings. From preparation to the plate, this recipe takes around 45 minutes. If you have chicken breast, ginger, chicken broth, and a few other ingredients on hand, you can make it. Not a lot of people really liked this main course. Pancit canton (a.k.a. lo mein or chow mein), Pancit canton (a.k.a.",
        "instructions": [
          "In a large nonstick skillet, heat oil; add ginger and garlic and cook over medium heat for 1 minute.",
          "Add chicken and carrot; cook over medium-high heat, stirring occasionally, until chicken is lightly browned, about 2 minutes.",
          "Add remaining ingredients except noodles; cook, stirring constantly, until carrot is tender-crisp, about 3 minutes.  Stir in noodles and cook until heated through, about 1 minute."
        ]
      },
      "nl": {
        "title": "Kip Lo Mein",
        "subtitle": "Chicken Lo Mein is een zuivelvrij recept met 2 porties.",
        "description": "Chicken Lo Mein is een zuivelvrij recept met 2 porties. Van bereiding tot op het bord duurt dit recept ongeveer 45 minuten. Als je kipfilet, gember, kippenbouillon en een paar andere ingrediënten bij de hand hebt, kun je het maken. Niet veel mensen vonden dit hoofdgerecht echt lekker.",
        "instructions": [
          "Verhit olie in een grote koekenpan met anti-aanbaklaag; voeg gember en knoflook toe en kook op middelhoog vuur gedurende 1 minuut.",
          "Voeg kip en wortel toe; kook op middelhoog vuur, af en toe roerend, tot de kip lichtbruin is, ongeveer 2 minuten.",
          "Voeg de resterende ingrediënten toe, behalve noedels; kook, onder voortdurend roeren, tot de wortel zacht en knapperig is, ongeveer 3 minuten.  Roer de noedels erdoor en kook tot ze warm zijn, ongeveer 1 minuut."
        ]
      },
      "fr": {
        "title": "Lo Mein au Poulet",
        "subtitle": "Le poulet Lo Mein est une recette sans produits laitiers avec 2 por...",
        "description": "Le poulet Lo Mein est une recette sans produits laitiers avec 2 portions. De la préparation à l'assiette, cette recette prend environ 45 minutes. 2 personnes ont réalisé cette recette et la referaient. Si vous avez de la poitrine de poulet, du gingembre, du bouillon de poulet et quelques autres ingrédients sous la main, vous pouvez le préparer. Peu de gens ont vraiment aimé ce plat principal.",
        "instructions": [
          "Dans une grande poêle antiadhésive, faire chauffer l'huile; ajouter le gingembre et l'ail et cuire à feu moyen pendant 1 minute.",
          "Ajouter le poulet et la carotte; cuire à feu moyen-vif, en remuant de temps en temps, jusqu'à ce que le poulet soit légèrement doré, environ 2 minutes.",
          "Ajouter le reste des ingrédients, sauf les nouilles. cuire en remuant constamment jusqu'à ce que la carotte soit tendre et croquante, environ 3 minutes.  Incorporer les nouilles et cuire jusqu'à ce qu'elles soient bien chaudes, environ 1 minute."
        ]
      }
    },
