        "title": "Pouding au pain brioché",
        "subtitle": "Le pudding au pain brioché nécessite environ 45 minutes du début à...",
        "description": "Le pudding au pain brioché nécessite environ 45 minutes du début à la fin. Cette recette en sert 8 personnes. Elle fonctionne bien comme dessert. Cette recette est appréciée par 3 gourmands et cuisiniers. Un mélange de lait, d'extrait de vanille, d'œufs et une poignée d'autres ingrédients suffisent pour rendre cette recette si savoureuse.",
